function eliiraValidationScope(node){return node?.closest?.('#overlay,.staff-profile-form,form')||document}
function eliiraClearFieldError(input){
  if(!input)return;
  const errorId=input.getAttribute('aria-errormessage')||'';
  if(errorId)document.getElementById(errorId)?.remove();
  input.removeAttribute('aria-invalid');input.removeAttribute('aria-errormessage');input.setAttribute('aria-describedby',(input.getAttribute('aria-describedby')||'').split(/\s+/).filter(id=>id&&id!==errorId).join(' '));if(!input.getAttribute('aria-describedby'))input.removeAttribute('aria-describedby');input.classList.remove('eliira-validation-invalid');
}
function eliiraClearValidation(scope=document){
  const root=scope||document;
  root.querySelectorAll?.('.eliira-field-error').forEach(error=>error.remove());
  root.querySelectorAll?.('.eliira-validation-invalid').forEach(input=>eliiraClearFieldError(input));
}
function eliiraBeginValidation(fieldId){eliiraClearValidation(eliiraValidationScope(document.getElementById(fieldId)));}
function eliiraFieldError(fieldId,message){
  const input=document.getElementById(fieldId);if(!input)return false;
  eliiraClearFieldError(input);
  const field=input.closest('.field')||input.parentElement,error=document.createElement('div'),errorId=fieldId+'_validation_error';
  error.id=errorId;error.className='eliira-field-error';error.setAttribute('role','alert');error.textContent=message;
  input.setAttribute('aria-invalid','true');input.setAttribute('aria-errormessage',errorId);input.setAttribute('aria-describedby',[...(input.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean),errorId].filter((id,index,all)=>all.indexOf(id)===index).join(' '));input.classList.add('eliira-validation-invalid');field.appendChild(error);
  const clear=()=>eliiraClearFieldError(input);input.addEventListener('input',clear,{once:true});input.addEventListener('change',clear,{once:true});
  input.scrollIntoView({block:'center'});input.focus({preventScroll:true});return false;
}
