function careLabel(id,window=false){if(id===null)return 'Preschool only';const p=daycarePlan(id);return p?`${p.name}${window?' · '+staffTimeLabel(p.start)+'–'+staffTimeLabel(p.end):''}`:'Needs staff review'}
