function placementFields(p={},prefix='placement'){
 const level=educationLevel(p.levelId)?.retired?'':p.levelId||'',rooms=educationConfig().classrooms.filter(r=>r.levelId===level);
 return `<div class="form-grid"><div class="field"><label for="${prefix}_level">Level</label><select id="${prefix}_level" onchange="refreshPlacementRooms('${prefix}')"><option value="">Select level…</option>${educationConfig().levels.filter(l=>!l.retired).map(l=>`<option value="${l.id}" ${l.id===level?'selected':''}>${esc(l.shortName||l.name)}</option>`).join('')}</select></div><div id="${prefix}_room_field">${educationRoomSelect(prefix+'_room',p.classroomId,rooms)}</div></div>`;
}
