function educationLearningState(s){return JSON.stringify(Object.values(s.curriculum?.weeks||{}).flatMap(weeks=>Object.values(weeks).flatMap(w=>Object.values(w.days).flat())).sort((a,b)=>a.uid.localeCompare(b.uid)))}
// One visible 12-hour field, with precise HH:mm retained for existing workflow writers.
function staffTimeValue(value){
 const match=/^(1[0-2]|[1-9]):([0-5]\d)\s*(AM|PM)$/i.exec(String(value).trim());
 return match?`${String(Number(match[1])%12+(match[3].toUpperCase()==='PM'?12:0)).padStart(2,'0')}:${match[2]}`:'';
}
function staffTimeField(label,value='',disabled=false,id='',context=''){
 const shown=value?staffTimeLabel(value):'';
 return `<div class="field"><label for="${id}_display">${label}</label><div class="staff-time-control" onfocusout="if(!this.contains(event.relatedTarget))closeStaffTimePicker(this)"><input id="${id}" type="hidden" value="${esc(value)}" ${disabled?'disabled':''}><input id="${id}_display" type="text" inputmode="text" role="combobox" aria-autocomplete="list" aria-controls="${id}_options" aria-label="${esc([context,label].filter(Boolean).join(' '))}" aria-expanded="false" autocomplete="off" placeholder="e.g. 8:15 AM" value="${esc(shown)}" ${disabled?'disabled':''} onfocus="openStaffTimePicker(this)" onpointerdown="staffTimeTriggerPointerDown(event,this)" oninput="syncStaffTime(this)" onkeydown="staffTimeInputKeydown(event,this)"><div id="${id}_options" class="staff-time-options" role="listbox" hidden>${Array.from({length:48},(_,i)=>{const time=staffTimeLabel(`${String(Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'}`);return `<button type="button" role="option" class="staff-time-option" data-time="${time}" aria-selected="${time===shown}" onkeydown="staffTimeOptionKeydown(event,this)" onclick="pickStaffTime(this)">${time}</button>`}).join('')}</div></div></div>`;
}
function closeStaffTimePicker(control){control.querySelector('.staff-time-options').hidden=true;control.querySelector('input[role=combobox]').setAttribute('aria-expanded','false')}
function staffTimeTriggerPointerDown(event,input){const control=input.parentElement;if(control.querySelector('.staff-time-options').hidden)return;event.preventDefault();input.focus();closeStaffTimePicker(control)}
function openStaffTimePicker(input){
 const control=input.parentElement;closeTemporaryMenus(control);
 const list=control.querySelector('.staff-time-options');
 list.querySelectorAll('button').forEach(button=>{button.hidden=false;button.setAttribute('aria-selected',String(button.dataset.time===input.value))});
 const body=input.closest('.modal-body'),roomBelow=body?body.getBoundingClientRect().bottom-input.getBoundingClientRect().bottom:innerHeight-input.getBoundingClientRect().bottom;
 list.classList.toggle('above',roomBelow<210);
 list.hidden=false;input.setAttribute('aria-expanded','true');
 const saved=control.querySelector('input[type=hidden]').value||'08:00',parts=/^(\d{2}):(\d{2})$/.exec(saved),minutes=parts?Number(parts[1])*60+Number(parts[2]):480;
 const nearby=list.querySelectorAll('button')[Math.min(47,Math.round(minutes/30))];
 if(nearby)list.scrollTop=Math.max(0,nearby.offsetTop-list.clientHeight/2);
}
function syncStaffTime(input){
 const control=input.closest('.staff-time-control'),list=control.querySelector('.staff-time-options');
 closeTemporaryMenus(control);
 control.querySelector('input[type=hidden]').value=staffTimeValue(input.value);
 list.hidden=false;input.setAttribute('aria-expanded','true');
 list.querySelectorAll('button').forEach(button=>button.hidden=!button.dataset.time.toLowerCase().includes(input.value.toLowerCase()));
}
function staffTimeInputKeydown(event,input){
 if(event.key==='Escape'){closeStaffTimePicker(input.parentElement);return}
 if(event.key==='ArrowDown'){
  event.preventDefault();if(input.parentElement.querySelector('.staff-time-options').hidden)openStaffTimePicker(input);
  const buttons=Array.from(input.parentElement.querySelectorAll('.staff-time-option')).filter(button=>!button.hidden);
  (buttons.find(button=>button.dataset.time===input.value)||buttons[0])?.focus();
 }
}
function staffTimeOptionKeydown(event,button){
 if(event.key==='Escape'){event.preventDefault();button.closest('.staff-time-control').querySelector('input[role=combobox]').focus();closeStaffTimePicker(button.closest('.staff-time-control'));return}
 if(!['ArrowDown','ArrowUp'].includes(event.key))return;
 event.preventDefault();const buttons=Array.from(button.parentElement.querySelectorAll('.staff-time-option')).filter(option=>!option.hidden),index=buttons.indexOf(button);
 buttons[(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();
}
function pickStaffTime(button){
 const control=button.closest('.staff-time-control'),input=control.querySelector('input[role=combobox]');
 input.value=button.dataset.time;control.querySelector('input[type=hidden]').value=staffTimeValue(input.value);
 input.dispatchEvent(new Event('change',{bubbles:true}));input.focus();closeStaffTimePicker(control);
}
// Shared dismissal for small, non-destructive menus and pickers.
function closeTemporaryMenus(except=null,restoreFocus=false){
 let closed=false;
 document.querySelectorAll('.account-area, .admissions-history-menu, .staff-photo-menu, .media-item-menu, .staff-time-control').forEach(root=>{
  if(root===except)return;
  if(root.classList.contains('account-area')){
   const menu=root.querySelector('.account-menu');if(!menu)return;
   mpsCloseAccountMenu();menu.remove();
   const trigger=root.querySelector('.account-trigger');trigger?.setAttribute('aria-expanded','false');
   if(restoreFocus)trigger?.focus();closed=true;
  }else if(root.classList.contains('admissions-history-menu')||root.classList.contains('staff-photo-menu')||root.classList.contains('media-item-menu')){
   if(!root.open)return;
   root.open=false;if(restoreFocus)root.querySelector('summary')?.focus();closed=true;
  }else{
   const list=root.querySelector('.staff-time-options');if(!list||list.hidden)return;
   if(restoreFocus)root.querySelector('input[role=combobox]')?.focus();
   closeStaffTimePicker(root);closed=true;
  }
 });
 return closed;
}
document.addEventListener('pointerdown',event=>{
 const root=event.target.closest?.('.account-area, .admissions-history-menu, .staff-photo-menu, .media-item-menu, .staff-time-control');
 closeTemporaryMenus(root);
},true);
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'&&closeTemporaryMenus(null,true))event.preventDefault();
});
document.addEventListener('toggle',event=>{
 const root=event.target;
 if(root.matches?.('.admissions-history-menu, .staff-photo-menu, .media-item-menu')&&root.open&&root.isConnected)closeTemporaryMenus(root);
},true);

