// Retain the exact old demo definitions as the compatibility boundary. Current
// library enrichment runs only after existing occurrences can be preserved.
function mpsOriginalDemoActivityLibrary(){return {
 colour_sort:{id:'colour_sort',title:'Colour sorting',sourceType:'MPS-provided activity',officialArea:'Numeracy',summary:'Sorting and grouping familiar objects by visible characteristics.',materials:'3 bowls · large safe red/blue/yellow objects'},
 picture_story:{id:'picture_story',title:'Picture-card story prompts',sourceType:'MPS-provided activity',officialArea:'Language and Early Literacy',summary:'Use familiar picture prompts to support vocabulary and simple sequencing.',materials:'Picture cards · story mat'},
 nature_walk:{id:'nature_walk',title:'Nature texture walk',sourceType:'Preschool-created activity',officialArea:'Environmental Exploration',summary:'Explore and describe safe natural textures in the preschool environment.',materials:'Collection basket · safe outdoor objects'},
 music_move:{id:'music_move',title:'Music and movement',sourceType:'MPS-provided activity',officialArea:'Creative Arts',summary:'Respond to rhythm through simple movement and imitation.',materials:'Speaker · scarves'}
}}
function mpsStageDemoActivityObjectives(original){
 // These are small demo-authored objectives, never source targets or evidence.
 const objectives={
  colour_sort:['Notice similarities and differences in object colours.','Sort familiar objects into matching colour groups.'],
  picture_story:['Use familiar pictures to practise descriptive vocabulary.','Put pictures in order to tell a simple story.'],
  nature_walk:['Notice different safe natural textures.','Use simple words to describe what the children find.'],
  music_move:['Explore rhythm through simple movements.','Practise imitating movements in time with music.']
 },defaults=mpsOriginalDemoActivityLibrary(),library=original.curriculum?.library||{};
 const ids=Object.keys(defaults).filter(id=>{
  const item=library[id];
  return item&&!Object.prototype.hasOwnProperty.call(item,'activityObjectives')&&
   Object.entries(defaults[id]).every(([key,value])=>item[key]===value)&&
   !item.authorship&&!item.sourceRef&&!item.curriculumLinks?.length;
 });
 if(!ids.length)return original;
 const next=mpsSourceCopy(original),before=Object.fromEntries(ids.map(id=>[id,mpsActivitySnapshot(library[id])]));
 // Pin precisely what an old occurrence resolved to before the library gains
 // new content. Existing occurrence snapshots and audit snapshots are untouched.
 for(const weeks of Object.values(next.curriculum.weeks||{}))for(const week of Object.values(weeks))for(const day of Object.values(week.days||{}))for(const occurrence of day){
  if(before[occurrence.libId]&&!occurrence.curriculumSourceSnapshot)occurrence.curriculumSourceSnapshot=mpsSourceCopy(before[occurrence.libId]);
 }
 for(const id of ids){
  const item=next.curriculum.library[id];item.activityObjectives=[...objectives[id]];
  if(!Array.isArray(item.learningAreas))item.learningAreas=[item.officialArea];
 }
 return next;
}
function migrateDemoActivityObjectives(){
 try{const staged=mpsStageDemoActivityObjectives(db);if(staged!==db){localStorage.setItem(storageKey,JSON.stringify(staged));db=staged}return true}
 catch(error){educationSaveBlocked=true;educationMigrationError=String(error.message||error);return false}
}
