function btn(label,action,kind='secondary',extra=''){return `<button class="btn ${kind} ${extra}" onclick="${action}">${label}</button>`}
function kv(k,v,extra=''){return `<div class="kv${extra?' '+extra:''}"><div class="k">${k}</div><div class="v">${v}</div></div>`}
function notice(text,type='info'){return `<div class="notice ${type}">${text}</div>`}
let mpsFeedbackTimer;
function showFeedback(message,anchor=null){
  let el=document.getElementById('eliira-feedback');
  if(!el){el=document.createElement('div');el.id='eliira-feedback';el.className='eliira-feedback';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.appendChild(el)}
  clearTimeout(mpsFeedbackTimer);el.className=anchor?'eliira-feedback eliira-feedback-inline':'eliira-feedback';
  if(anchor)anchor.insertAdjacentElement('afterend',el);else document.body.appendChild(el);
  el.textContent=message;el.hidden=false;
  if(anchor)el.scrollIntoView({block:'nearest'});
  mpsFeedbackTimer=setTimeout(()=>{el.hidden=true;el.textContent=''},4000);
}
function field(label,value='',type='text',disabled=false,id=''){if(type==='time')return staffTimeField(label,value,disabled,id);return `<div class="field"><label>${label}</label><input ${id?`id="${id}"`:''} type="${type}" value="${esc(value)}" ${disabled?'disabled':''}></div>`}
function selectField(label,options,value='',id='',onchange=''){return `<div class="field"><label>${label}</label><select ${id?`id="${id}"`:''} ${onchange?`onchange="${onchange}"`:''}>${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
function textArea(label,value='',id=''){return `<div class="field"><label>${label}</label><textarea ${id?`id="${id}"`:''}>${esc(value)}</textarea></div>`}
function checked(v){return v?'checked':''}
