function selectedActivityArea(w=currentWeek()){const area=ui().lessonActivityArea;return lessonLearningAreas(w).includes(area)?area:''}
function selectedActivityType(){const type=ui().lessonActivityType;return Object.hasOwn(mpsActivityTypeLabels,type)?type:''}
