function activitySearchValue(){return typeof ui().lessonActivitySearch==='string'?ui().lessonActivitySearch:''}
function activityBrowseUniverse(){const area=selectedActivityArea(),type=selectedActivityType(),origin=selectedActivityOrigin();return mpsLessonLibrary(currentWeek()).filter(lib=>lessonActivityBelongsToPack(lib)&&(!area||mpsLearningAreas(mpsResolveActivity(lib)).includes(area))&&(!type||mpsActivityType(lib)===type)&&(!origin||mpsActivityOriginLabel(lib)===origin))}
