function setActivityAreaFilter(area){ui().lessonActivityArea=lessonLearningAreas().includes(area)?area:'';clearIncompatibleActivitySubarea();refreshActivityBrowsers();if(selectedActivityArea())document.querySelectorAll('[data-activity-browser] [data-b09-area]').forEach(group=>{if(group.dataset.b09AreaName===selectedActivityArea())group.open=true})}
function setActivityTypeFilter(type){ui().lessonActivityType=Object.hasOwn(mpsActivityTypeLabels,type)?type:'';clearIncompatibleActivitySubarea();refreshActivityBrowsers()}
