function activityAreaFilter(suffix=''){const selected=selectedActivityArea(),id='activityLearningAreaFilter'+suffix;return `<div class="field activity-area-filter"><label for="${id}">Learning Area</label><select id="${id}" data-activity-area-filter onchange="setActivityAreaFilter(this.value)"><option value="" ${selected?'':'selected'}>All learning areas</option>${lessonLearningAreas().map(area=>`<option value="${esc(area)}" ${area===selected?'selected':''}>${esc(area)}</option>`).join('')}</select></div>`}
function activityTypeFilter(suffix=''){const selected=selectedActivityType(),id='activityTypeFilter'+suffix;return `<div class="field activity-type-filter"><label for="${id}">Activity type</label><select id="${id}" data-activity-type-filter onchange="setActivityTypeFilter(this.value)"><option value="" ${selected?'':'selected'}>All activity types</option>${Object.entries(mpsActivityTypeLabels).map(([type,label])=>`<option value="${esc(type)}" ${selected===type?'selected':''}>${esc(label)}</option>`).join('')}</select></div>`}
function activityOriginFilter(suffix=''){const selected=selectedActivityOrigin(),id='activityOriginFilter'+suffix;return `<div class="field activity-origin-filter"><label for="${id}">From</label><select id="${id}" data-activity-origin-filter onchange="setActivityOriginFilter(this.value)"><option value="" ${selected?'':'selected'}>All</option>${activityOriginOptions().map(origin=>`<option value="${esc(origin)}" ${selected===origin?'selected':''}>${esc(origin)}</option>`).join('')}</select></div>`}
function activitySubareaFilter(suffix=''){const area=selectedActivityArea(),options=activitySubareaOptions(),id='activitySubareaFilter'+suffix,selected=selectedActivitySubarea();return `<div class="field activity-subarea-filter"><label for="${id}">Sub-area</label><select id="${id}" data-activity-subarea-filter onchange="setActivitySubareaFilter(this.value)" ${options.length?'':'disabled'}><option value="">${area?(options.length?'All sub-areas':'No sub-areas available'):'Choose a Learning Area first'}</option>${options.map(subarea=>`<option value="${esc(subarea.id)}" ${selected===subarea.id?'selected':''}>${esc(subarea.label)}</option>`).join('')}</select></div>`}
