function lessonEvidenceVisibility(visibility){return ['Parent-eligible','Parent-eligible candidate'].includes(visibility)?{text:'Parent-eligible',tone:'green'}:{text:'Internal',tone:'blue'}}
function lessonEvidenceObservation(o){const visibility=lessonEvidenceVisibility(o.visibility);return `<article class="lesson-evidence-item" data-evidence-type="observation" data-evidence-id="${esc(o.id)}"><header><div><strong>${profileChildLink(o.childId,o.childName)}</strong><div class="lesson-evidence-tags">${badge('Observation','blue')}</div>${mpsLearningAreaContextHtml(o,true)}</div>${badge(visibility.text,visibility.tone)}</header><p class="lesson-evidence-text">${esc(o.text)}</p><div class="lesson-evidence-context"><span>${esc(o.activityTitle||'Teaching activity')}</span>${o.date?`<span>${fmtDate(o.date)}</span>`:''}${o.photo?'<span>Photo attached</span>':''}</div><footer>${btn('Open progress',`openDrawer('child-progress',{childId:'${esc(o.childId)}'})`,'secondary','sm')}</footer></article>`}
