renderLessonEvidence=function(){const ids=new Set(learningChildren().map(c=>c.id)),obs=Object.values(db.observations).filter(o=>ids.has(profileChildId(o.childId))),ass=Object.values(db.assessments).filter(a=>ids.has(profileChildId(a.childId))),items=[...obs.map(record=>({type:'observation',record})),...ass.map(record=>({type:'assessment',record}))].sort((a,b)=>String(b.record.date||'').localeCompare(String(a.record.date||'')));return `<section class="card flat lesson-evidence"><div class="lesson-evidence-heading"><h3>Learning evidence</h3><p>Observations and assessments recorded through normal teaching.</p></div><div class="lesson-evidence-list">${items.map(item=>item.type==='observation'?lessonEvidenceObservation(item.record):lessonEvidenceAssessment(item.record)).join('')||'<div class="empty">No observations or assessments yet.</div>'}</div></section>`}
