  return drawer(lib.title,editable?'Review this activity for your class.':'View the approved planned activity and its source context.',`${mpsB09DetailHtml(mpsLibraryActivity(p.a.libId,p.wk),null,p.a.guidanceSnapshot,true)}<div class="section-title planned-change-title">Your changes — optional</div>${classBody}${mpsOriginalActivityHtml(lib,p.a.guidanceSnapshot)}`,editable?`${btn('Close','closeOverlay()','secondary')}${btn('Save changes',`saveAdaptation('${p.a.uid}')`,'primary')}`:btn('Close','closeOverlay()','secondary'));
