function mpsReturnFromSchoolTermSetup(){
 const destination=mpsTermSetupReturn;mpsTermSetupReturn=null;if(!destination)return false;
 ui().lessonClass=destination.classroomId;ui().lessonWeek=destination.week;setRoute('lessons');openActivityPicker(destination.day);document.querySelector('.drawer [data-activity-search]')?.focus();return true;
}
// BQ-129: managed NIE Theme definitions belong to Eliira; month selection remains Head Teacher-owned.
function mpsUsesManagedNieThemes(){return mpsSelectedCurriculumPack()?.id===MPS_DEFAULT_CURRICULUM_PACK_ID}
function mpsThemeTopics(){const curated=Object.fromEntries(mpsProvisionalDiscovery.themes.map(t=>[t.id,t]));return mpsUsesManagedNieThemes()?{...(db.curriculum.themeTopics||{}),...curated}:{...curated,...(db.curriculum.themeTopics||{})}}
function mpsPreschoolThemes(){return db.curriculum.themeTopics||{}}
function mpsAvailableThemes(){const topics=mpsUsesManagedNieThemes()?mpsProvisionalDiscovery.themes:Object.values(mpsThemeTopics());return topics.filter(t=>!t.archived&&!t.demo).sort((a,b)=>a.name.localeCompare(b.name))}
function mpsMonthThemes(){return db.curriculum.monthThemes||{}}
function mpsActivityThemeTags(){return db.curriculum.activityThemeTags||{}}
function mpsValidMonth(month){return /^\d{4}-(0[1-9]|1[0-2])$/.test(month||'')}
function mpsMonthLabel(month){return mpsValidMonth(month)?new Date(month+'-01T12:00:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}):''}
function mpsThemeForMonth(month){const a=mpsMonthThemes()[month],t=a?.themeId&&mpsThemeTopics()[a.themeId];return t?{...t,name:a.themeSnapshot?.name||t.name,month}:a?.themeSnapshot?{...a.themeSnapshot,month}:null}
function mpsThemeForDate(date){return educationDate(date)?mpsThemeForMonth(date.slice(0,7)):null}
function mpsMonthsForWeek(start){return [...new Set(lessonWeekDays().map((_,i)=>isoAddDays(start,i).slice(0,7)))]}
function mpsCanSetMonthTheme(){return mpsCurrentAccount()?.status==='active'&&has('Head Teacher')}
function mpsCanManageThemes(){return !mpsUsesManagedNieThemes()&&mpsCanSetMonthTheme()}
function mpsSaveMonthTheme(month,themeId){
 if(!mpsCanSetMonthTheme()||!mpsValidMonth(month))return false;
 const t=themeId?mpsAvailableThemes().find(theme=>theme.id===themeId):null;if(themeId&&!t)return false;
 const old=mpsMonthThemes()[month];if((old?.themeId||null)===(themeId||null))return true;
 const actor=staffActor(),at=new Date().toISOString(),before={themeId:old?.themeId||null,name:old?.themeSnapshot?.name||mpsThemeTopics()[old?.themeId]?.name||''},after={themeId:themeId||null,name:t?.name||''};
 db.curriculum.monthThemes=db.curriculum.monthThemes||{};
 db.curriculum.monthThemes[month]={month,themeId:themeId||null,themeSnapshot:t?{id:t.id,name:t.name}:null,changedBy:actor,changedAt:at,history:[...(old?.history||[]),...(old?[{before,after,actor,at}]:[])]};
 ui().modal=null;save();render();return true;
}
function saveMonthTheme(month){return mpsSaveMonthTheme(month,val('month_theme_id'))}
function mpsSavePreschoolTheme(id,name,description){
 if(!mpsCanManageThemes()||(id&&!mpsPreschoolThemes()[id]))return false;
 name=String(name||'').trim();description=String(description||'').trim();const old=id?mpsPreschoolThemes()[id]:null;
 if(old?.archived)return false;
 if(!name||name.length>80||Object.values(mpsThemeTopics()).some(t=>t.id!==id&&!t.archived&&t.name.toLocaleLowerCase()===name.toLocaleLowerCase()))return eliiraFieldError('preschool_theme_name','Enter a unique theme name of up to 80 characters.');
 if(description.length>240)return eliiraFieldError('preschool_theme_description','Keep the description within 240 characters.');
 const actor=staffActor(),at=new Date().toISOString(),themeId=id||'local_theme_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);
 db.curriculum.themeTopics=db.curriculum.themeTopics||{};
 db.curriculum.themeTopics[themeId]={...old,id:themeId,name,description,origin:'preschool',archived:false,history:[...(old?.history||[]),...(old?[{type:'edited',before:{name:old.name,description:old.description||''},after:{name,description},actor,at}]:[])]};
 ui().modal=null;save();render();return themeId;
}
function savePreschoolTheme(id){return mpsSavePreschoolTheme(id,val('preschool_theme_name'),val('preschool_theme_description'))}
function mpsArchivePreschoolTheme(id){
 const t=mpsPreschoolThemes()[id];if(!mpsCanManageThemes()||!t||t.archived)return false;
 if(!confirm(`Archive ${t.name}? It will remain in existing plans and month history.`))return false;
 const actor=staffActor(),at=new Date().toISOString();t.archived=true;t.history=[...(t.history||[]),{type:'archived',before:{archived:false},after:{archived:true},actor,at}];
 ui().drawer=null;save();render();return true;
}
function mpsThemeAssociatedIds(themeId){return mpsLessonLibrary(currentWeek()).filter(lib=>mpsActivityHasTheme(lib,themeId)).map(lib=>lib.id)}
function mpsSaveThemeAssociations(themeId,ids){
 const t=mpsPreschoolThemes()[themeId];if(!mpsCanManageThemes()||!t||t.archived||!Array.isArray(ids))return false;
 const available=new Set(mpsLessonLibrary(currentWeek()).filter(lib=>lessonActivityBelongsToPack(lib)).map(lib=>lib.id));if(ids.some(id=>!available.has(id)))return false;
 const chosen=new Set(ids),before=mpsThemeAssociatedIds(themeId),actor=staffActor(),at=new Date().toISOString();db.curriculum.activityThemeTags=db.curriculum.activityThemeTags||{};
 for(const id of available){const tags=(db.curriculum.activityThemeTags[id]||[]).filter(tag=>tag!==themeId);if(chosen.has(id))tags.push(themeId);if(tags.length)db.curriculum.activityThemeTags[id]=tags;else delete db.curriculum.activityThemeTags[id];const local=db.curriculum.library[id];if(local?.sourceType==='Preschool-created activity')local.themeIds=(local.themeIds||[]).filter(tag=>tag!==themeId)}
 t.history=[...(t.history||[]),{type:'associations',before,after:[...chosen],actor,at}];ui().drawer=null;save();render();return true;
}
function saveThemeAssociations(themeId){return mpsSaveThemeAssociations(themeId,Array.from(document.querySelectorAll('[data-theme-association]:checked')).map(input=>input.value))}
function filterThemeAssociations(query){const q=String(query||'').trim().toLocaleLowerCase();document.querySelectorAll('[data-theme-association-row]').forEach(row=>{row.hidden=!!q&&!row.dataset.search.includes(q)})}
function mpsMonthContextHtml(){
 const room=educationRoom(ui().lessonClass);if(!room||!mpsTeachingAccess(room.id))return '';
 const months=mpsMonthsForWeek(ui().lessonWeek||TODAY);
 return `<section class="month-theme-context ${months.length===1?'single-month':''}" data-month-theme-context><div class="month-theme-heading">${months.length>1?'Themes this week':'This month’s theme'}${mpsCanManageThemes()?`<details class="month-theme-tools"><summary aria-label="Theme options" title="Theme options">⋯</summary><div>${btn('Manage themes',"openDrawer('preschool-themes')",'secondary','sm')}</div></details>`:''}</div>${months.map(month=>{const theme=mpsThemeForMonth(month);return `<div class="month-theme-row" data-month="${esc(month)}"><div><strong>${esc(mpsMonthLabel(month))}</strong><span>${theme?esc(theme.name):'No theme set'}</span></div>${mpsCanSetMonthTheme()?btn(theme?'Change theme':'Set theme',`openModal('month-theme',{month:'${month}'})`,'secondary','sm'):''}</div>`}).join('')}</section>`;
}
function mpsActivityHasTheme(lib,themeId){return !!themeId&&[...(mpsProvisionalDiscovery.activities[lib?.id]?.themeIds||[]),...(lib?.themeIds||[]),...(mpsActivityThemeTags()[lib?.id]||[])].includes(themeId)}
function mpsActivityIsCore(lib){return !!mpsProvisionalDiscovery.activities[lib?.id]?.core}
function mpsDiscoverySnapshot(lib,day){const date=day?lessonDayDate(day):null,theme=mpsThemeForDate(date),guidance=mpsB09Activity(lib,mpsB09Context(day));return {month:date?.slice(0,7)||null,theme:theme?{id:theme.id,name:theme.name}:null,themeMatched:!!theme&&mpsActivityHasTheme(lib,theme.id),core:guidance?guidance.coreBands.length>0:null}}
function mpsThemeForBrowseDay(day){const date=day?lessonDayDate(day):ui().lessonWeek||TODAY;return mpsThemeForDate(date)}
function mpsThemeSuggestionsAvailable(theme){return !!theme&&mpsLessonLibrary(currentWeek()).some(lib=>lessonActivityBelongsToPack(lib)&&mpsActivityHasTheme(lib,theme.id))}
let mpsLevelSetupReturn=null;
function mpsOpenLevelPlanningSetup(day){
 if(!has('Head Teacher')||!allowed('preschool-settings'))return false;
 const room=educationRoom(ui().lessonClass);
 mpsLevelSetupReturn={classroomId:ui().lessonClass,week:ui().lessonWeek,day};
 mpsOpenPreschoolSettings();
 const section=Array.from(document.querySelectorAll('.preschool-settings .settings-section')).find(item=>item.querySelector(':scope > summary')?.textContent.trim()==='Levels');
 if(section){section.open=true;const field=section.querySelector(`[data-level-id="${room?.levelId}"] [data-level-range]`)||section.querySelector('[data-level-range]');field?.scrollIntoView({block:'center'});field?.focus({preventScroll:true})}
 return true;
}
function mpsReturnFromLevelPlanningSetup(){
 const destination=mpsLevelSetupReturn;mpsLevelSetupReturn=null;if(!destination)return false;
 ui().lessonClass=destination.classroomId;ui().lessonWeek=destination.week;setRoute('lessons');openActivityPicker(destination.day);document.querySelector('.drawer [data-activity-search]')?.focus();return true;
}
function mpsThemeBrowserIntro(day){
 if(!day)return '';
 const date=lessonDayDate(day),month=date?.slice(0,7),theme=mpsThemeForDate(date),context=mpsB09Context(day),room=educationRoom(ui().lessonClass),level=room&&educationLevel(room.levelId),unsupported=!!level&&!mpsB09BandsForRange(level.minMonths,level.maxMonths),all=!!ui().lessonThemeBrowseAll,state=mpsSchoolTermState(date),missing=!context&&!unsupported&&state.kind==='missing';
 const heading=context?(all?'Full library':'Recommended for this class'):unsupported?'Level planning band needs review':state.kind==='gap'?'Between school terms':state.kind==='missing'?'School terms need setup':'Classroom guidance unavailable';
 return `<div class="activity-theme-intro ${context&&!all?'activity-theme-intro-guided':''}" data-theme-intro><div class="activity-theme-main"><div><strong>${esc(heading)}</strong>${context?`<span>${esc(mpsMonthLabel(month))} · ${esc(level?.name||'Level')} · Ages ${esc(context.range)} · ${esc(context.termName)} · ${theme?esc(theme.name):'No month theme'}</span>`:`<span>${esc(mpsMonthLabel(month))} · ${theme?esc(theme.name):'No month theme'}</span><small>${esc(missing&&mpsCanManageSchoolTerms()?'Set up the school term so Eliira can suggest activities for this class.':mpsB09GuidanceState(day))}</small>`}</div><div class="activity-theme-actions">${unsupported&&has('Head Teacher')&&allowed('preschool-settings')?btn('Choose planning band',`mpsOpenLevelPlanningSetup('${day}')`,'primary','sm'):''}${missing&&mpsCanManageSchoolTerms()?btn('Set up school terms',`mpsOpenSchoolTermSetup('${day}')`,'primary','sm'):''}${context&&all?btn('Back to recommendations','setActivityThemeBrowseAll(false)','secondary','sm'):context?'':missing?btn(all?'Hide full library':'Browse all activities','setActivityThemeBrowseAll('+(!all)+')','secondary','sm'):btn('Browse full library','jumpToAllActivities()','secondary','sm')}</div></div></div>`;
}
function jumpToAllActivities(){document.querySelector('[data-discovery-section="all"]')?.scrollIntoView({block:'start'})}
function setActivityThemeBrowseAll(show){ui().lessonThemeBrowseAll=!!show;save();refreshActivityBrowsers()}
const mpsMonthThemeBaseModalView=modalView;
modalView=function(m){
 if(m?.name==='month-theme'){const month=m.data?.month;if(!mpsCanSetMonthTheme()||!mpsValidMonth(month))return modal('Theme unavailable','',notice('Only the Head Teacher can set a month theme.','info'),btn('Close','closeOverlay()'));
  const selected=mpsMonthThemes()[month]?.themeId||'';return modal('Month theme',`${mpsMonthLabel(month)} · one theme for the whole preschool`,`<div class="field"><label for="month_theme_id">Theme</label><select id="month_theme_id"><option value="">No theme</option>${mpsAvailableThemes().map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`,`${btn('Cancel','closeOverlay()','secondary')}${btn('Save theme',`saveMonthTheme('${month}')`,'primary')}`)}
 if(m?.name==='preschool-theme-edit'){const id=m.data?.id,t=id?mpsPreschoolThemes()[id]:null;if(!mpsCanManageThemes()||(id&&(!t||t.archived)))return modal('Theme unavailable','',notice('Theme catalogue management is unavailable.','info'),btn('Close','closeOverlay()'));
  return modal(t?'Edit theme':'Create theme','For this preschool’s activity choices.',`${field('Theme name',t?.name||'','text',false,'preschool_theme_name')}${textArea('Short description — optional',t?.description||'','preschool_theme_description')}`,`${btn('Cancel','closeOverlay()','secondary')}${btn('Save theme',`savePreschoolTheme(${id?`'${id}'`:'null'})`,'primary')}`)}
 return mpsMonthThemeBaseModalView(m)
};
const mpsMonthThemeBaseDrawerView=drawerView;
drawerView=function(d){
 if(d.name==='preschool-themes'){if(!mpsCanManageThemes())return drawer('Themes','',notice('Theme catalogue management is unavailable.','info'));
  const items=Object.values(mpsPreschoolThemes()).sort((a,b)=>a.name.localeCompare(b.name));return drawer('Preschool themes','Create and manage themes for this preschool.',`<div class="theme-manager-actions">${btn('Create theme',"openModal('preschool-theme-edit')",'primary','sm')}</div><div class="theme-manager-list">${items.map(t=>`<article class="theme-manager-item"><strong>${esc(t.name)}</strong>${t.archived?badge('Archived','grey'):''}${t.description?`<p>${esc(t.description)}</p>`:''}<div>${t.archived?'':`${btn('Edit',`openModal('preschool-theme-edit',{id:'${t.id}'})`,'secondary','sm')}${btn('Activities',`openDrawer('preschool-theme-associations',{id:'${t.id}'})`,'secondary','sm')}${btn('Archive',`mpsArchivePreschoolTheme('${t.id}')`,'secondary','sm')}`}</div></article>`).join('')||'<p>No preschool themes created yet.</p>'}</div>`)}
 if(d.name==='preschool-theme-associations'){const t=mpsPreschoolThemes()[d.data?.id];if(!mpsCanManageThemes()||!t||t.archived)return drawer('Theme unavailable','',notice('Theme catalogue management is unavailable.','info'));
  const selected=new Set(mpsThemeAssociatedIds(t.id)),items=mpsLessonLibrary(currentWeek()).filter(lib=>lessonActivityBelongsToPack(lib)).map(lib=>mpsResolveActivity(lib)).sort((a,b)=>a.title.localeCompare(b.title));return drawer(t.name,'Choose activities that fit this theme.',`<div class="field"><label for="theme_activity_search">Find activity</label><input id="theme_activity_search" type="search" oninput="filterThemeAssociations(this.value)" placeholder="Search the library…"></div><div class="theme-association-list">${items.map(lib=>`<label class="check-row" data-theme-association-row data-search="${esc((lib.title+' '+mpsActivityOriginLabel(lib)).toLocaleLowerCase())}"><input type="checkbox" data-theme-association value="${esc(lib.id)}" ${selected.has(lib.id)?'checked':''}><span>${esc(lib.title)}<small>${esc(mpsActivityOriginLabel(lib))}</small></span></label>`).join('')}</div>`,`${btn('Back',"openDrawer('preschool-themes')",'secondary')}${btn('Save activities',`saveThemeAssociations('${t.id}')`,'primary')}`)}
 return mpsMonthThemeBaseDrawerView(d)
};

// Owner Issue 003 — keep Admissions service choices symmetric across preschool classes.
function selectField(label,options,value='',id='',onchange=''){
  return `<div class="field"><label>${label}</label><select ${id?`id="${id}"`:''} ${onchange?`onchange="${onchange}"`:''}>${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`
}

// Owner Issue 004 — keep Admissions overview simple: one action, one concise details card.
function admissionOverview(c){
  let d=admissionDerived(c),action='';
  if(d.stage==='Enquiry')action=actionCard('Next action · Review qualification','Confirm genuine family, relevant age/start, real admission interest and permission to follow up.',btn('Review qualification',`openModal('qualify-lead',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Qualified')action=actionCard('Next action · Arrange a tour','Keep the appointment on the same family history.',btn('Schedule tour',`openModal('schedule-tour',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Tour'&&c.tour?.status==='scheduled')action=actionCard('Next action · Complete tour',`${fmtDate(c.tour.date)} · ${c.tour.time}. Record the real outcome after the visit.`,btn('Complete tour',`openModal('complete-tour',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Tour')action=actionCard('Next action · Send secure application','Tour is complete and the family wants to proceed.',btn('Send application',`openModal('send-application',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.status==='Waiting for parent')action=actionCard('Waiting for parent','The secure Application link is active. Staff can resend/copy it without leaving this record.',`${btn('Open parent preview',`openParentApplication('${c.id}')`,'secondary','sm')}${btn('Resend link',`openModal('send-application',{caseId:'${c.id}'})`,'secondary','sm')}`);
  else if(d.status==='Review required')action=actionCard('Next action · Review submitted application','The parent submission is now part of this same case.',btn('Review application',"setAdmissionTab('application')",'primary','sm'));
  else if(d.status==='Fee overdue')action=actionCard('Admission fee overdue','The place is not released automatically. An authorised decision is required.',btn('Review overdue',`openModal('overdue-fee',{caseId:'${c.id}'})`,'primary','sm'),'warning');
  else if(d.status==='Admission fee')action=actionCard('Admission fee in progress',`${money(c.fee.amount-c.fee.verified)} verified balance remaining.`,btn('Open payments',"setAdmissionTab('payments')",'primary','sm'));
  else if(d.status==='Fee satisfied')action=actionCard('Fee gate satisfied','Create the enrolment from the accepted Application; do not retype the family.',btn('Create enrolment',`openModal('create-enrolment',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Enrolled')action=actionCard(`Pre-start · ${d.status}`,'Parent onboarding and staff review live here; safety readiness is separate from non-critical checklist completion.',btn('Open pre-start',"setAdmissionTab('prestart')",'primary','sm'),d.status==='Pre-start review'?'warning':'');
  return `${action}<div class="card" style="margin-top:12px"><h3>Admission details</h3>${kv('Lead source',`${c.source} ${prov('Recorded in Admissions','staff')}`)}${kv('Reason for choice',c.reason||'—')}${kv('Tour',c.tour?`${c.tour.status} · ${fmtDate(c.tour.date)} ${c.tour.time||''}`:'Not yet scheduled')}${kv('Application',applicationSummary(c))}${kv('Planned start',fmtDate(c.start))}</div>`
}

// Owner Issue 005 — one plain-language Admissions stage vocabulary across the staff UI.
const admissionStageLabels=['Enquiry','Confirmed Interest','Visit','Application','Accepted','Admission Fee','Enrolled','Ready to Start'];

function admissionDisplayStage(c){
  let d=admissionDerived(c);
  if(c.closed?.type==='Duplicate')return 'Duplicate';
  if(c.closed)return 'Closed';
  if(d.stage==='Enquiry')return 'Enquiry';
  if(d.stage==='Qualified')return 'Confirmed Interest';
  if(d.stage==='Tour')return 'Visit';
  if(d.stage==='Application')return 'Application';
  if(d.stage==='Accepted'&&c.fee)return 'Admission Fee';
  if(d.stage==='Accepted')return 'Accepted';
  if(d.stage==='Enrolled')return d.status==='Ready to start'?'Ready to Start':'Enrolled';
  return d.stage;
}
function admissionCondition(c){
  let d=admissionDerived(c),stage=admissionDisplayStage(c);
  if(c.closed)return 'Closed';
  if(c.migrationHistory)return 'Current at migration · historical context';
  if(admissionHandoffComplete(c))return 'Admissions completed · Current child';
  if(c.enrolment?.start&&c.enrolment.start<=TODAY&&!admissionRequiredReadinessComplete(c))return 'Planned start reached · required pre-start work outstanding';
  if(stage==='Enquiry')return 'Confirm interest';
  if(stage==='Confirmed Interest')return 'Arrange visit';
  if(stage==='Visit')return c.tour?.status==='scheduled'?'Visit scheduled':'Visit completed · send application';
  if(stage==='Application'){
    if(d.status==='Waiting for parent')return 'Waiting for parent';
    if(d.status==='Review required')return 'Needs review';
    if(d.status==='Waitlisted')return 'Waitlisted';
    if(d.status==='Declined')return 'Declined';
    return 'Application in progress';
  }
  if(stage==='Accepted')return 'Waiting for Billing';
  if(stage==='Admission Fee'){
    if(d.status==='Fee overdue')return 'Payment overdue';
    if(d.status==='Fee satisfied')return 'Payment complete · enrol child';
    return 'Payment pending';
  }
  if(stage==='Enrolled')return d.status==='Pre-start review'?'Application information needs review':d.status==='Pre-start'?'Pre-start in progress':'Complete pre-start review';
  if(stage==='Ready to Start')return 'Ready for first day';
  return d.next||'';
}
function admissionStageTone(c){
  let stage=admissionDisplayStage(c),d=admissionDerived(c);
  if(stage==='Closed'||stage==='Duplicate')return 'grey';
  if(stage==='Admission Fee'&&d.status==='Fee overdue')return 'red';
  if(stage==='Admission Fee')return 'amber';
  if(stage==='Ready to Start'||stage==='Accepted'||stage==='Confirmed Interest')return 'green';
  if(stage==='Application')return d.status==='Review required'?'purple':'blue';
  return 'blue';
}
journey=function(c){let steps=['Enquiry','Confirmed Interest','Visit','Application','Accepted','Admission Fee','Enrolled','Ready to Start'];let current=admissionStageIndex(c);return `<div class="journey">${steps.map((s,i)=>`<div class="journey-step ${i<current?'done':i===current?'current':''}"><span class="dot">${i<current?'✓':i+1}</span>${s}</div>`).join('')}</div>`};
function admissionsFilteredCases(){let filter=ui().admissionsStageFilter||'All';return Object.values(db.admissions).filter(c=>filter==='All'||admissionDisplayStage(c)===filter)}
function setAdmissionsStageFilter(stage){ui().admissionsStageFilter=stage;let matches=admissionsFilteredCases();if(matches.length&&!matches.some(c=>c.id===ui().admissionsCase))ui().admissionsCase=matches[0].id;save();render()}
admissionsMetrics=function(){let all=Object.values(db.admissions),active=ui().admissionsStageFilter||'All';let stages=['All',...admissionStageLabels];return `<div class="tabs" style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:0">${stages.map(stage=>{let count=stage==='All'?all.length:all.filter(c=>admissionDisplayStage(c)===stage).length;return `<button class="tab ${active===stage?'active':''}" data-stage-filter="${esc(stage)}" onclick='setAdmissionsStageFilter(${JSON.stringify(stage)})'>${stage} <strong>${count}</strong></button>`}).join('')}</div>`};
admissionsList=function(){let cases=admissionsFilteredCases();return `<div class="case-list"><div class="case-search"><input placeholder="Search admissions…" oninput="filterAdmissions(this.value)"></div><div id="admissionsCaseItems">${cases.length?cases.map(caseListItem).join(''):(ui().admissionsStageFilter==='Completed admissions'?'<div class="empty" style="padding:16px">No completed admissions yet.</div>':ui().admissionsStageFilter==='Duplicates'?'<div class="empty" style="padding:16px">No resolved duplicates.</div>':Object.keys(db.admissions).length===0?'<div class="empty" style="padding:16px">No enquiries yet.</div>':'<div class="empty" style="padding:16px">No families in this stage.</div>')}</div></div>`};
caseListItem=function(c){let stage=admissionDisplayStage(c),condition=admissionCondition(c);return `<div class="case-item ${ui().admissionsCase===c.id?'active':''}" data-stage="${esc(stage)}" data-search="${esc((c.childName+' '+c.guardian+' '+stage+' '+condition).toLowerCase())}" onclick="setAdmissionCase('${c.id}')"><div class="top"><strong>${c.childName}</strong><span style="margin-left:auto">${badge(stage,admissionStageTone(c))}</span></div><div class="meta">${c.guardian} · ${c.service}${condition?`<br>${esc(condition)}`:''}</div></div>`};
filterAdmissions=function(q){q=(q||'').toLowerCase();document.querySelectorAll('#admissionsCaseItems .case-item').forEach(el=>el.style.display=el.dataset.search.includes(q)?'block':'none')};
admissionHero=function(c){let stage=admissionDisplayStage(c);return `<div class="case-hero"><div class="case-hero-row"><div class="case-avatar">${c.childName.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div class="case-title"><h2>${c.childName}</h2><p>${c.guardian} · ${c.phone} · Start ${fmtDate(c.enrolment?c.enrolment.start:c.start)}<br>${c.service}</p></div><div class="case-status">${badge(stage,admissionStageTone(c))}</div></div>${journey(c)}</div>`};
function admissionCaseWorkspace(c){
  let content=renderAdmissionTab(c);
  const tabContent=html=>ui().admissionsTab==='application'?`<div class="admissions-application-stack ui-peer-stack">${html}</div>`:html;
  const tabs=c.closed?.type==='Duplicate'||admissionIsHistorical(c)?'':admissionTabs();
  if(c.closed||admissionIsHistorical(c))return `${admissionHero(c)}${tabs}${tabContent(content)}`;
  // The existing Overview action is the case action. Move that same control
  // above the tabs so it stays available while staff inspect other tabs.
  const actionSource=document.createElement('div');
  actionSource.innerHTML=ui().admissionsTab==='overview'?content:admissionOverview(c);
  const first=actionSource.firstElementChild;
  const action=first?.classList.contains('action-card')?first.outerHTML:'';
  if(action&&ui().admissionsTab==='overview'){
    first.remove();
    content=actionSource.innerHTML;
  }
  return `${admissionHero(c)}${action}${tabs}${tabContent(content)}`;
}
renderAdmissions=function(){let matches=admissionsFilteredCases(),filter=ui().admissionsStageFilter||'All',hasCases=Object.keys(db.admissions).length>0,c=matches.find(x=>x.id===ui().admissionsCase)||matches[0]||null;if(c)ui().admissionsCase=c.id;let workspace=c?admissionCaseWorkspace(c):(filter==='Duplicates'?'<div class="card"><h3>No resolved duplicates</h3><p>Confirmed duplicate records will appear here.</p></div>':!hasCases?'<div class="card operational-empty"><h3>No enquiries yet</h3><p>Start with New enquiry when a family contacts the preschool.</p></div>':'<div class="card"><h3>No families in this stage</h3><p>Choose another admission stage to continue.</p></div>');return shell(`${pageHead('Admissions','Admissions','One clear admission journey. Choose a stage, open a family, and do the next real job.',btn('New enquiry',"openModal('new-enquiry')",c?'secondary':'primary')).replace('class="page-head"','class="page-head admissions-page-head"')}${hasCases?`${admissionsMetrics()}<div style="height:14px"></div>${admissionsCaseSwitcher(c)}<div class="case-layout">${admissionsList()}<div class="case-workspace">${workspace}</div></div>`:`<div class="case-workspace admissions-empty-workspace">${workspace}</div>`}`)};
applicationSummary=function(c){let s=c.application.status;let labels={not_sent:'Not sent',sent:'Sent · waiting for parent',submitted:'Submitted · needs review',accepted:'Accepted',waitlisted:'Waitlisted',declined:'Declined'};return labels[s]||s};
function admissionVisitTimeField(value){
  const choices=Array.from({length:48},(_,i)=>`${String(Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'}`),other=!!value&&!choices.includes(value);
  return `<div class="field"><label for="tour_time_choice">Visit time</label><input id="tour_time" type="hidden" value="${esc(value)}"><select id="tour_time_choice" onchange="admissionVisitTimeChanged()">${choices.map(time=>`<option value="${time}" ${time===value?'selected':''}>${staffTimeLabel(time)}</option>`).join('')}<option value="other" ${other?'selected':''}>Another time…</option></select><div id="tour_time_custom_wrap" ${other?'':'hidden'}><label for="tour_time_custom">Enter visit time</label><input id="tour_time_custom" type="text" inputmode="text" placeholder="e.g. 10:17 AM" value="${other?esc(staffTimeLabel(value)):''}" oninput="admissionVisitTimeChanged()"></div><small id="tour_time_error" class="form-error" hidden>Choose a valid Visit time.</small></div>`;
}
function admissionVisitTimeChanged(){
  const other=val('tour_time_choice')==='other',custom=byId('tour_time_custom_wrap');custom.hidden=!other;
  byId('tour_time').value=other?staffTimeValue(val('tour_time_custom')):val('tour_time_choice');
  byId('tour_time_error').hidden=true;
  if(other)byId('tour_time_custom')?.focus();
}
function admissionScheduleVisit(id){
  if(!val('tour_time')){byId('tour_time_error').hidden=false;byId('tour_time_custom')?.focus();return false}
  return scheduleTour(id);
}
admissionOverview=function(c){
  let d=admissionDerived(c),action='';
  if(d.stage==='Enquiry')action=actionCard('Next action · Confirm interest','Confirm this is a genuine admission enquiry, the child fits the intake, and the family wants us to continue.',btn('Confirm interest',`openModal('qualify-lead',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Qualified')action=actionCard('Next action · Arrange visit','Keep the visit on the same family admission record.',btn('Schedule visit',`openModal('schedule-tour',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Tour'&&c.tour?.status==='scheduled')action=actionCard('Next action · Complete visit',`${fmtDate(c.tour.date)} · ${c.tour.time}. Record what actually happened after the visit.`,btn('Complete visit',`openModal('complete-tour',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Tour')action=actionCard('Next action · Send application','The visit is complete and the family wants to proceed.',btn('Send application',`openModal('send-application',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.status==='Waiting for parent')action=actionCard('Waiting for parent','The secure application link is active. Staff can resend it without leaving this family record.',`${btn('Open parent preview',`openParentApplication('${c.id}')`,'secondary','sm')}${btn('Resend link',`openModal('send-application',{caseId:'${c.id}'})`,'secondary','sm')}`);
  else if(d.status==='Review required')action=actionCard('Next action · Review application','The parent submission is now part of this same admission record.',btn('Review application',"setAdmissionTab('application')",'primary','sm'));
  else if(d.status==='Fee overdue')action=actionCard('Admission Fee · Payment overdue','The place is not released automatically. An authorised decision is required.',btn('Review overdue',`openModal('overdue-fee',{caseId:'${c.id}'})`,'primary','sm'),'warning');
  else if(d.status==='Admission fee')action=actionCard('Admission Fee · Payment pending',`${money(c.fee.amount-c.fee.verified)} verified balance remaining.`,btn('Open payments',"setAdmissionTab('payments')",'primary','sm'));
  else if(d.status==='Fee satisfied')action=actionCard('Admission Fee · Payment complete','Create the enrolment from the accepted application; do not retype the family.',btn('Create enrolment',`openModal('create-enrolment',{caseId:'${c.id}'})`,'primary','sm'));
  else if(d.stage==='Enrolled'){
    const ready=admissionRequiredReadinessComplete(c);
    const activation=ready&&typeof mpsSignedApplicationActivationAction==='function'?mpsSignedApplicationActivationAction(c):'';
    const reviewAction=!ready&&ui().admissionsTab!=='prestart'?btn('Review pre-start',"setAdmissionTab('prestart')",'primary','sm'):'';
    action=ready
      ?actionCard(c.enrolment?.status==='pending_start'?'Ready to start':'Start requirements met',c.enrolment?.status==='pending_start'?`Starts ${fmtDate(c.enrolment.start)} · Safety and required start checks are complete.`:'Safety and required start checks are complete.',activation)
      :actionCard('Pre-start needs attention','Required start checks still need attention.',reviewAction,'warning');
  }
  return `${action}<div class="card" style="margin-top:12px"><h3>Admission details</h3>${kv('Lead source',`${c.source} ${prov('Recorded in Admissions','staff')}`)}${kv('Reason for choice',c.reason||'—')}${kv('Visit',c.tour?`${c.tour.status} · ${fmtDate(c.tour.date)} ${c.tour.time||''}`:'Not yet scheduled')}${kv('Application',applicationSummary(c))}${kv('Planned start',fmtDate(c.enrolment?c.enrolment.start:c.start))}</div>`
};

const _mpsAdmissionPlainModalView=modalView;
modalView=function(m){let n=m.name,d=m.data||{};
  if(n==='qualify-lead'){let c=db.admissions[d.caseId];return modal('Confirm interest','Confirm this is a genuine admission enquiry and the family wants us to continue.',`${kv('Family',`${c.guardian} / ${c.childName}`)}${kv('Age / desired start','Relevant for intake')}${kv('Admission interest','Confirmed')}${kv('Follow-up permission','Yes')}${notice('A visit is not required to confirm interest. Ability to pay is not part of this decision.','info')}`,`${btn('Keep as enquiry','closeOverlay()','secondary')}${btn('Confirm interest',`qualifyCase('${c.id}')`,'primary')}`)}
  if(n==='schedule-tour'){let c=db.admissions[d.caseId];return modal('Schedule visit','Keep the visit on the same admission record.',`<div class="form-grid admission-visit-fields">${field('Visit date',c.tour?.date||'2026-09-18','date',false,'tour_date')}${admissionVisitTimeField(c.tour?.time||'10:30')}</div>${field('Attending contact',c.tour?.contact||c.guardian,'text',false,'tour_contact')}`,`${btn('Cancel','closeOverlay()','secondary')}${btn('Schedule visit',`admissionScheduleVisit('${c.id}')`,'primary')}`)}
  if(n==='complete-tour'){let c=db.admissions[d.caseId];return modal('Complete visit','Record what actually happened.',`${selectField('Outcome',['Family wants to proceed','Follow-up needed','Family not proceeding'],'Family wants to proceed','tour_outcome')}${textArea('Factual note','Family liked the classroom and wants to continue.','tour_note')}`,`${btn('Cancel','closeOverlay()','secondary')}${btn('Save outcome',`completeTour('${c.id}')`,'primary')}`)}
  if(n==='send-application'){let c=db.admissions[d.caseId];return modal('Send secure application','No parent account required.',`${kv('Recipient',`${c.guardian} · ${c.phone}`)}${kv('Expires','7 days from generation')}${kv('Prefill','Enquiry + Visit information')}${field('Secure link',`https://apply.mps.example/a/${c.id.toUpperCase()}-6V2K`,'text',true)}${textArea('Prepared WhatsApp message',`Hi ${c.guardian.split(' ')[0]}, thank you for visiting ${mpsOrganisationName()}. Please use this secure link to review the details we already have and submit ${c.childName.split(' ')[0]}’s application.`,'app_message')}${notice('Manual WhatsApp records Sent only — not Delivered or Read.','info')}`,`${btn('Cancel','closeOverlay()','secondary')}${btn('Copy & mark Sent',`sendApplication('${c.id}')`,'primary')}`)}
  return _mpsAdmissionPlainModalView(m)
};
// Owner Issue 006 — clarify lean Application vs full New Family Onboarding and keep internal navigation out of parent UI.
function exitParentPreview(){
  const id=ui().parentApplicationCase;
  if(ui().route==='parent-application'&&applicationFamilyEditable(id)&&!syncApplicationDraft(id)){applicationFocusSaveError();return}
  const previous={route:ui().route,admissionsCase:ui().admissionsCase,admissionsTab:ui().admissionsTab,admissionsStageFilter:ui().admissionsStageFilter,parentApplicationStep:ui().parentApplicationStep};
  ui().route='admissions';
  ui().admissionsCase=db.admissions[id]?id:ui().admissionsCase;
  ui().admissionsTab='application';
  ui().admissionsStageFilter='All';
  ui().parentApplicationStep=1;
  if(!applicationSaveNavigation()){Object.assign(ui(),previous);applicationFocusSaveError();return}
  render();
}

renderParentApplication=function(){
  let id=ui().parentApplicationCase,c=db.admissions[id];
  if(!c){ui().route='admissions';save();return renderAdmissions()}
  let d=c.application.draft||(c.application.draft={childName:c.childName,dob:c.dob,guardian:c.guardian,phone:c.phone,service:c.service,start:c.start});
  let s=ui().parentApplicationStep;
  let explainer=notice("This application only confirms the basic details needed to review your child's application. If your child is enrolled, we'll send a separate secure New Family Onboarding form before their first day for family, emergency, pickup and Health information.",'info');
  let body=s===1?`${explainer}<div class="form-grid">${field('Child full name',d.childName,'text',false,'pa_childName')}${field('Date of birth',d.dob,'date',false,'pa_dob')}${field('Parent / guardian',d.guardian,'text',false,'pa_guardian')}${field('Registered phone',d.phone,'text',false,'pa_phone')}</div>${selectField('Interested service',['Baby Class','Upper Class','Baby Class + Standard Daycare','Baby Class + Extended Daycare','Upper Class + Standard Daycare','Upper Class + Extended Daycare'],d.service,'pa_service')}${field('Desired start',d.start,'date',false,'pa_start')}`:`${notice("If your child is enrolled, the separate New Family Onboarding form will collect the remaining family, emergency, authorised pickup, Health, communication and consent information.",'ok')}${selectField('Please confirm the information above is accurate',['Yes — submit','No — I need to correct something'],'Yes — submit','pa_confirm')}`;
  let footer=s===1?`<span></span>${btn('Continue',`appContinue('${id}')`,'primary')}`:`${btn('Back',`syncApplicationDraft('${id}');ui().parentApplicationStep=1;save();render()`,'secondary')}${btn('Submit application',`submitApplication('${id}')`,'primary')}`;
  return `<div class="parent-view"><div style="max-width:680px;margin:0 auto 8px;display:flex;justify-content:flex-end;align-items:center;gap:8px"><span style="font-size:11px;color:#60758a">Prototype review only</span>${btn('Exit parent preview','exitParentPreview()','secondary','sm')}</div><div class="parent-card"><div class="parent-brand"><strong>${ORG}</strong><p>Secure Application · no MPS account required</p></div><div class="parent-content"><div class="stepper"><span class="active"></span><span class="${s===2?'active':''}"></span></div><div class="eyebrow">Application for ${esc(c.childName)}</div><h2 style="color:var(--navy);font-size:20px;margin:5px 0 12px">${s===1?'Review your details':'Confirm & submit'}</h2>${body}<div class="parent-foot">${footer}</div></div></div></div>`
};
