// BQ-094 — Account Admin, profile/settings and password recovery.
// One real person keeps one account. Account Admin is an access capability, not a
// separate identity and not an automatic grant of operational/business authority.

const MPS_ACCOUNT_ADMIN = 'Account Admin';


function mpsUnique(values){return [...new Set((values||[]).filter(Boolean))]}
function mpsRandomCode(prefix='RECOVERY'){
  return `${prefix}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;
}
function mpsAccount(id){return db.staff?.accounts?.[id]||null}
function mpsCurrentAccount(){return mpsAccount(currentPersona().id)}
function mpsIsAccountAdminAccount(account){return !!account&&account.status==='active'&&(account.bundles||[]).includes(MPS_ACCOUNT_ADMIN)}
function mpsActiveAccountAdmins(){return Object.values(db.staff?.accounts||{}).filter(mpsIsAccountAdminAccount)}
function mpsAccountAdminCount(){return mpsActiveAccountAdmins().length}
function mpsCurrentIsAccountAdmin(){return mpsIsAccountAdminAccount(mpsCurrentAccount())||has(MPS_ACCOUNT_ADMIN)}
function mpsEnsurePersonaForAccount(account){
  if(!account) return;
  if(!db.personas[account.id]){
    db.personas[account.id]={id:account.id,name:account.name,initials:String(account.name||'Staff').split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase(),bundles:[...(account.bundles||[])],scope:account.scope||'All'};
  }else{
    db.personas[account.id].name=account.name;
    db.personas[account.id].bundles=[...(account.bundles||[])];
    db.personas[account.id].scope=account.scope||db.personas[account.id].scope||'All';
  }
}
function mpsMigrateAccountAdminModel(){
  let changed=false;
  if(db.ui?.modal?.name==='my-profile'){db.ui.modal=null;db.ui.route='staff';db.ui.profileStaff=db.ui.persona;db.ui.staffProfileSection='Profile';changed=true}
  if(db.prototypeFixture==='clean'&&!db.ownerAccessDefaultVersion){
    const owner=db.staff?.accounts?.anjali,edited=(db.staff?.history||[]).some(e=>e.staffId==='anjali'&&e.text?.includes('access updated'));
    if(owner&&!edited)owner.bundles=mpsUnique([...owner.bundles,'Social Media']);
    db.ownerAccessDefaultVersion=1;changed=true;
  }
  db.organization=db.organization||{name:ORG,contactPhone:'',timezone:'Asia/Colombo',settingsHistory:[]};
  if(!db.organization.name){db.organization.name=ORG;changed=true}
  if(!db.organization.timezone){db.organization.timezone='Asia/Colombo';changed=true}
  if(!db.organization.curriculum){db.organization.curriculum={primaryPackId:MPS_DEFAULT_CURRICULUM_PACK_ID,adoptionDate:null};changed=true}
  db.organization.settingsHistory=db.organization.settingsHistory||[];

  Object.values(db.staff?.accounts||{}).forEach(a=>{
    const before=(a.bundles||[]).join('|');
    a.bundles=mpsUnique((a.bundles||[]).map(b=>b==='System Administration'?MPS_ACCOUNT_ADMIN:b));
    if(before!==a.bundles.join('|')) changed=true;
    mpsEnsurePersonaForAccount(a);
  });

  // Current tenant prototype starts with the Head Teacher as the first authorised
  // workspace user, while retaining the former admin sample as a second Account Admin.
  const initial=mpsAccount('anjali')||Object.values(db.staff?.accounts||{}).find(a=>a.status==='active');
  if(db.prototypeFixture!=='clean'&&initial&&!initial.bundles.includes(MPS_ACCOUNT_ADMIN)){
    initial.bundles.push(MPS_ACCOUNT_ADMIN);
    initial.bundles=mpsUnique(initial.bundles);
    mpsEnsurePersonaForAccount(initial);
    changed=true;
  }

  Object.values(db.personas||{}).forEach(p=>{
    const account=mpsAccount(p.id);
    if(account){
      const next=[...(account.bundles||[])];
      if(JSON.stringify(p.bundles)!==JSON.stringify(next)){p.bundles=next;changed=true}
    }else if((p.bundles||[]).includes('System Administration')){
      p.bundles=mpsUnique(p.bundles.map(b=>b==='System Administration'?MPS_ACCOUNT_ADMIN:b));
      changed=true;
    }
  });


  // BQ-101 Staff identity is visible to staff; account actions retain Account Admin guards.
  routes.staff.bundles=null;
  if(changed) save();
}

function mpsOrganisationName(){return db.organization?.name||ORG}
function mpsTimezoneLabel(value){
  const map={
    'Asia/Colombo':'Sri Lanka — Colombo (UTC+05:30)',
    'Asia/Kolkata':'India — Kolkata (UTC+05:30)',
    'Asia/Dubai':'United Arab Emirates — Dubai (UTC+04:00)',
    'Europe/London':'United Kingdom — London',
    'UTC':'UTC'
  };
  return map[value]||value||'Not set';
}
function mpsTimezoneOptions(selected){
  const options=[
    ['Asia/Colombo','Sri Lanka — Colombo (UTC+05:30)'],
    ['Asia/Kolkata','India — Kolkata (UTC+05:30)'],
    ['Asia/Dubai','United Arab Emirates — Dubai (UTC+04:00)'],
    ['Europe/London','United Kingdom — London'],
    ['UTC','UTC']
  ];
  if(selected&&!options.some(x=>x[0]===selected)) options.push([selected,selected]);
  return options.map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');
}

function mpsToggleAccountMenu(){const opening=!ui().accountMenuOpen;if(opening)closeTemporaryMenus(document.querySelector('.account-area'));ui().accountMenuOpen=opening;save();render();document.querySelector('.account-trigger')?.focus()}
function mpsCloseAccountMenu(){ui().accountMenuOpen=false;save()}
function mpsOpenAccountModal(name){if(name==='my-profile'){mpsOpenOwnStaffProfile();return}ui().accountMenuOpen=false;ui().modal={name,data:null};save();render()}
let mpsOwnStaffReturn=null;
function mpsOpenOwnStaffProfile(){
  const a=mpsCurrentAccount();if(!a)return;
  const previous={route:ui().route,profileStaff:ui().profileStaff,section:ui().staffProfileSection};
  const changed=previous.route!=='staff'||previous.profileStaff!==a.id;
  openStaffProfile(a.id);
  if(changed){mpsOwnStaffReturn=previous;history.pushState({mpsOwnStaffProfile:true,previous},'')}
}
window.addEventListener('popstate',event=>{
  if(event.state?.mpsOwnStaffProfile){mpsOwnStaffReturn=event.state.previous;const a=mpsCurrentAccount();if(a)openStaffProfile(a.id);return}
  if(!mpsOwnStaffReturn||ui().route!=='staff'||ui().profileStaff!==mpsCurrentAccount()?.id)return;
  const previous=mpsOwnStaffReturn;mpsOwnStaffReturn=null;
  ui().profileStaff=previous.profileStaff;ui().staffProfileSection=previous.section;setRoute(previous.route);
});
function mpsAccountMenuHtml(){
  const p=currentPersona();
  return `<div class="account-area"><button class="account-trigger" aria-label="Account menu for ${esc(p.name)}" aria-expanded="${ui().accountMenuOpen?'true':'false'}" onclick="mpsToggleAccountMenu()"><span class="user-meta"><b>${esc(p.name)}</b><span>${esc((p.bundles||[]).join(' · '))}</span></span><span class="avatar">${esc(p.initials||'') }</span><span class="account-caret">▾</span></button>${ui().accountMenuOpen?`<div class="account-menu" role="menu"><button role="menuitem" onclick="mpsOpenOwnStaffProfile()"><strong>My profile</strong></button><button role="menuitem" onclick="mpsPrototypeSignOut()"><strong>Sign out</strong></button></div>`:''}</div>`;
}

const _mpsAccountBaseShell=shell;
shell=function(content){
  const p=currentPersona();
  let html=_mpsAccountBaseShell(content);
  const old=`<div class="user-meta"><b>${p.name}</b><span>${p.bundles.join(' · ')}</span></div><div class="avatar">${p.initials}</div>`;
  html=html.replace(old,mpsAccountMenuHtml());
  html=html.split(ORG).join(mpsOrganisationName());
  return html;
};

const _mpsAccountBaseSetRoute=setRoute;
setRoute=function(route){ui().accountMenuOpen=false;_mpsAccountBaseSetRoute(route)};

function mpsSavePreschoolSettings(){
  if(!mpsCurrentIsAccountAdmin()){showFeedback('Account Admin access is required.');return}
  const o=db.organization;
  const nextName=val('org_name').trim();
  const nextPhone=val('org_phone').trim();
  const nextTimezone=val('org_timezone');
  if(!nextName)return eliiraFieldError('org_name','Enter the preschool name.');
  if(nextTimezone!==o.timezone&&!confirm(`Change the preschool timezone from ${mpsTimezoneLabel(o.timezone)} to ${mpsTimezoneLabel(nextTimezone)}? This changes how the preschool interprets and displays operational times.`)) return;
  const changes=[];
  if(nextName!==o.name) changes.push(`name: ${o.name} → ${nextName}`);
  if(nextPhone!==o.contactPhone) changes.push('contact phone updated');
  if(nextTimezone!==o.timezone) changes.push(`timezone: ${o.timezone} → ${nextTimezone}`);
  o.name=nextName;o.contactPhone=nextPhone;o.timezone=nextTimezone;
  if(changes.length)o.settingsHistory.push({at:new Date().toISOString(),by:currentPersona().name,byId:currentPersona().id,changes});
  save();closeOverlay();
}

function mpsBundleOptions(){return ['Head Teacher','Class Teacher','Assistant Teacher','Daycare','Admissions','Accounts','Social Media','Medication administration','Family legal review',MPS_ACCOUNT_ADMIN]}
function mpsTeachingClassroomsRequired(bundles){return (bundles||[]).some(b=>['Class Teacher','Assistant Teacher'].includes(b))}
function mpsSelectedResponsibilityBundles(){return mpsUnique(Array.from(document.querySelectorAll('#overlay [data-bundle]:checked')).map(x=>x.value).filter(b=>mpsBundleOptions().includes(b)))}
function mpsRefreshTeachingClassrooms(id){
  const field=byId(id);if(!field)return;
  const visible=mpsTeachingClassroomsRequired(mpsSelectedResponsibilityBundles());
  field.hidden=!visible;
  field.querySelectorAll('[data-staff-room]').forEach(input=>input.disabled=!visible);
}
function mpsResponsibilityFields(selected=[],roomId='access_rooms'){
  return `<fieldset class="staff-responsibilities"><legend>Responsibilities</legend>${mpsBundleOptions().map(b=>`<label class="check-row"><input data-bundle type="checkbox" value="${b}" ${checked(selected.includes(b))} onchange="mpsRefreshTeachingClassrooms('${roomId}')"> ${b}</label>`).join('')}</fieldset>`;
}
function mpsManageAccessModal(id){
  const a=mpsAccount(id);if(!a)return modal('Manage access','',notice('Staff account not found.','warn'),btn('Close','closeOverlay()','secondary'));
  const isLast=mpsIsAccountAdminAccount(a)&&mpsAccountAdminCount()===1;
  return modal('Manage access','One account can hold several responsibilities without role switching.',`${mpsResponsibilityFields(a.bundles||[])}${staffRoomFields(a)}${a.classroomReview?notice('Previous classroom assignments need review. Select the confirmed classrooms before saving teaching access.','warn'):''}${isLast?notice('This is the last active Account Admin. Give Account Admin access to someone else before removing or deactivating this account.','warn'):''}${a.status==='inactive'?notice('This account remains inactive while you correct its access. Review the saved access before reactivating it.','info'):''}${notice('Account Admin manages MPS accounts and basic preschool settings. It does not automatically grant access to Admissions, Billing, Health, teaching or other preschool work.','info')}`,`${btn('Cancel','closeOverlay()','secondary')}${a.status==='inactive'?'':btn('Deactivate account',`mpsOpenStaffDeactivation('${a.id}')`,'danger')}${btn('Save access',`saveAccess('${a.id}')`,'primary')}`);
}
saveAccess=function(id){
  if(!mpsCurrentIsAccountAdmin())return;
  const a=mpsAccount(id);if(!a)return;
  const beforeDb=JSON.parse(JSON.stringify(db));
  const next=mpsSelectedResponsibilityBundles();
  const removingLast=(a.bundles||[]).includes(MPS_ACCOUNT_ADMIN)&&!next.includes(MPS_ACCOUNT_ADMIN)&&mpsAccountAdminCount()===1;
  if(removingLast){showFeedback('Eliira must always have at least one active Account Admin. Give Account Admin access to another active staff member first.');return}
  const rooms=readStaffRooms();if((a.classroomReview||a.status==='inactive')&&mpsTeachingClassroomsRequired(next)&&!rooms.length){showFeedback('Choose an active teaching classroom before saving this access.');return}
  const before={bundles:[...a.bundles],classroomIds:[...(a.classroomIds||[])],classrooms:(a.classroomIds||[]).map(id=>({id,label:classroomLabel(id,true)}))};
  a.bundles=next;a.classroomIds=rooms;a.classroomReview=false;a.legacyChildAccess=[];
  mpsEnsurePersonaForAccount(a);
  db.staff.history.push({actor:staffActor(),staffId:a.id,at:new Date().toISOString(),before,after:{bundles:[...next],classroomIds:[...rooms],classrooms:rooms.map(id=>({id,label:classroomLabel(id,true)}))},text:`${a.username} access updated: ${a.bundles.join(', ')}`});
  ui().modal=null;if(!save()){db=beforeDb;return}render();showFeedback('Access saved.');
};
function mpsStaffLifecycleSnapshot(a,data=db){const identity=a.identityId?data.auth?.identities?.[a.identityId]:null,tokens=Object.values(data.auth?.tokens||{}).filter(t=>t.identityId===a.identityId&&!t.usedAt&&!t.revokedAt).map(t=>({id:t.id,purpose:t.purpose,expiresAt:t.expiresAt}));return JSON.stringify({name:a.name,status:a.status,deactivatedFromStatus:a.deactivatedFromStatus||null,bundles:a.bundles||[],classroomIds:a.classroomIds||[],classroomReview:!!a.classroomReview,legacyChildAccess:a.legacyChildAccess||[],scope:a.scope||'',profile:a.profile||null,identityId:a.identityId||null,identity:identity?{email:identity.email,emailVerified:identity.emailVerified,credentialVersion:identity.credentialVersion,googleSubject:identity.googleSubject,pendingEmail:identity.pendingEmail}:null,tokens})}
function mpsStaffLifecyclePersisted(a){
  try{const saved=JSON.parse(localStorage.getItem(storageKey));return !!saved?.staff?.accounts?.[a.id]&&mpsStaffLifecycleSnapshot(saved.staff.accounts[a.id],saved)===mpsStaffLifecycleSnapshot(a)}catch(_error){return false}
}
function mpsStaffLifecycleStoreCurrent(){
  try{const saved=JSON.parse(localStorage.getItem(storageKey));return JSON.stringify(saved?.staff)===JSON.stringify(db.staff)&&JSON.stringify(saved?.auth)===JSON.stringify(db.auth)}catch(_error){return false}
}
function mpsStaffLifecycleProblem(message){showFeedback(message);return false}
function mpsOpenStaffDeactivation(id){
  const a=mpsAccount(id);
  if(!mpsCurrentIsAccountAdmin()||!a||!['active','pending_profile'].includes(a.status))return mpsStaffLifecycleProblem('This account is no longer available for deactivation.');
  ui().modal={name:'confirm-staff-deactivation',data:{id,snapshot:mpsStaffLifecycleSnapshot(a)}};render();return true;
}
function mpsStaffDeactivationModal(id){
  const a=mpsAccount(id);if(!mpsCurrentIsAccountAdmin()||!a)return '';
  return modal('Deactivate account','',`${kv('Staff member',esc(a.name))}<p>This will disable this person’s access to Eliira. Their Staff record and past actions will remain.</p>`,`${btn('Cancel','closeOverlay()','secondary')}${btn('Confirm deactivation',`deactivateStaff('${esc(id)}')`,'danger')}`);
}
deactivateStaff=function(id){
  const a=mpsAccount(id),confirmation=ui().modal;
  if(!mpsCurrentIsAccountAdmin()||!a||confirmation?.name!=='confirm-staff-deactivation'||confirmation.data?.id!==id)return false;
  if(!mpsStaffLifecyclePersisted(mpsCurrentAccount()))return mpsStaffLifecycleProblem('Your Account Admin access could not be confirmed. Reload and review the account before trying again.');
  if(!['active','pending_profile'].includes(a.status)||confirmation.data.snapshot!==mpsStaffLifecycleSnapshot(a)||!mpsStaffLifecyclePersisted(a))return mpsStaffLifecycleProblem('This Staff account changed. Reload it and review the current access before trying again.');
  if(!mpsStaffLifecycleStoreCurrent())return mpsStaffLifecycleProblem('Saved Staff information changed. Reload before trying again.');
  if(mpsIsAccountAdminAccount(a)&&mpsAccountAdminCount()===1)return mpsStaffLifecycleProblem('This is the last active Account Admin. Give Account Admin access to another active staff member before deactivating this account.');
  const before=structuredClone(db),actor=staffActor(),at=new Date().toISOString();
  a.deactivatedFromStatus=a.status;a.status='inactive';
  if(a.identityId)mpsInvalidateTokens(a.identityId,['reset','invite','email-change']);
  db.staff.history.push({actor,staffId:id,at,before:{status:before.staff.accounts[id].status},after:{status:'inactive'},text:`${a.name} account deactivated; access disabled`});
  ui().modal=null;
  if(!save()){db=before;return mpsStaffLifecycleProblem('Account was not deactivated. Check browser storage and try again.')}
  render();showFeedback(`${a.name} account deactivated.`);return true;
};
function mpsAccountAdminToday(){
  const p=currentPersona();
  const operational=(p.bundles||[]).some(b=>b!==MPS_ACCOUNT_ADMIN);
  if(operational) return null;
  return shell(`${pageHead('Today','Today','Manage the preschool account and staff access.')}${notice('You have Account Admin access only. Operational child, teaching, Admissions, Billing and Health information is not included automatically.','info')}<div class="grid" style="margin-top:14px"><div class="span-6 card"><h3>Staff</h3><p>Add staff, resend invitations or update access.</p>${btn('Open Staff',"setRoute('staff')",'primary')}</div><div class="span-6 card"><h3>Preschool settings</h3><p>Update basic preschool account settings such as the preschool timezone.</p>${btn('Open Preschool settings',"mpsOpenPreschoolSettings()",'secondary')}</div></div>`);
}
