// Small settings forms; business configuration stays Head Teacher-owned.
function educationAgeYears(months){return Number((months/12).toFixed(4))}
function educationAgeMonths(value){
 const years=Number(value),months=Math.round(years*12);
 return String(value).trim()!==''&&Number.isFinite(years)&&years>=0&&Number.isSafeInteger(months)&&Math.abs(years*12-months)<0.001?months:null;
}
// Expected-age bands use completed months and half-open [start, end) intervals.
// Saved legacy conflicts stay readable; a configuration write cannot introduce
// a new conflict or change either range in a still-conflicting pair.
function educationActiveRangeConflicts(config){
 const levels=config.levels.filter(level=>!level.retired),conflicts=[];
 for(let i=0;i<levels.length;i++)for(let j=i+1;j<levels.length;j++){
  const a=levels[i],b=levels[j];
  if(Number.isSafeInteger(a.minMonths)&&Number.isSafeInteger(a.maxMonths)&&a.minMonths<a.maxMonths&&Number.isSafeInteger(b.minMonths)&&Number.isSafeInteger(b.maxMonths)&&b.minMonths<b.maxMonths&&a.minMonths<b.maxMonths&&b.minMonths<a.maxMonths)conflicts.push([a,b]);
 }
 return conflicts;
}
function educationRangeWriteError(before,after){
 for(const [a,b] of educationActiveRangeConflicts(after)){
  const oldA=before.levels.find(level=>level.id===a.id),oldB=before.levels.find(level=>level.id===b.id);
  const unchanged=oldA&&oldB&&!oldA.retired&&!oldB.retired&&oldA.minMonths===a.minMonths&&oldA.maxMonths===a.maxMonths&&oldB.minMonths===b.minMonths&&oldB.maxMonths===b.maxMonths;
  if(unchanged)continue;
  const edited=oldA&&!oldA.retired&&oldA.minMonths===a.minMonths&&oldA.maxMonths===a.maxMonths?b:a;
  const other=edited===a?b:a;
  return {levelId:edited.id,message:`This age range overlaps with ${other.name} (${educationLevelRangeLabel(other)}). Choose a different range.`};
 }
 return null;
}
function educationExistingConflictHtml(config){
 const conflicts=educationActiveRangeConflicts(config);
 if(!conflicts.length)return '';
 return `<div class="settings-level-conflicts" role="status">${conflicts.map(([a,b])=>notice(`${esc(a.name)} (${esc(educationLevelRangeLabel(a))}) overlaps with ${esc(b.name)} (${esc(educationLevelRangeLabel(b))}). Edit a Level to resolve this saved conflict; existing children and Classrooms stay as recorded.`,'warn')).join('')}</div>`;
}
function educationPlanningRangeField(level){
 const choices=mpsB09PlanningRanges(),value=`${level.minMonths}|${level.maxMonths}`,supported=!!mpsB09BandsForRange(level.minMonths,level.maxMonths),id=`level_range_${level.id}`;
 return `<div class="field education-planning-range"><label for="${esc(id)}">Planning age band</label><select id="${esc(id)}" data-level-range onchange="refreshEducationLevelSummary('${esc(level.id)}')">${supported?'':`<option value="${esc(value)}" selected>Existing range needs review (${esc(educationAgeYears(level.minMonths))}–${esc(educationAgeYears(level.maxMonths))} years)</option>`}${choices.map(([min,max])=>`<option value="${min}|${max}" ${value===`${min}|${max}`?'selected':''}>Ages ${min/12}–${max/12}</option>`).join('')}</select><small>Choose one planning band for this Level. Children keep their exact dates of birth and placement.</small></div>`;
}
function educationLevelFields(l){
 const id=esc(l.id),age=`${educationAgeYears(l.minMonths)} → ${educationAgeYears(l.maxMonths)} years`;
 return `<div class="education-level" data-level-id="${id}"><div class="education-level-head"><strong data-level-name>${esc(l.name||'New level')}</strong><span data-level-ages>${age}</span>${btn('Remove',`removeEducationLevel('${l.id}')`,'secondary','sm')}</div><div class="form-grid"><div class="field"><label for="level_name_${id}">Level name</label><input id="level_name_${id}" type="text" value="${esc(l.name)}" oninput="refreshEducationLevelSummary('${l.id}')"></div>${field('Short name',l.shortName,'text',false,'level_short_'+l.id)}</div>${educationPlanningRangeField(l)}</div>`;
}
function refreshEducationLevelSummary(id){
 const row=Array.from(document.querySelectorAll('[data-level-id]')).find(el=>el.dataset.levelId===id);
 if(!row)return;
 row.querySelector('[data-level-name]').textContent=val('level_name_'+id).trim()||'New level';
 const [min,max]=val('level_range_'+id).split('|').map(Number);row.querySelector('[data-level-ages]').textContent=`${min/12} → ${max/12} years`;
 const group=Array.from(document.querySelectorAll('[data-room-group-level]')).find(el=>el.dataset.roomGroupLevel===id);
 if(group)group.querySelector('[data-room-level-name]').textContent=val('level_name_'+id).trim()||'New level';
}
function educationLevelReferenced(id){
 const visit=value=>value&&typeof value==='object'&&Object.entries(value).some(([key,part])=>(key==='levelId'&&part===id)||visit(part));
 return !!visit(db);
}
function removeEducationLevel(id){
 if(!has('Head Teacher'))return;
 const row=Array.from(document.querySelectorAll('[data-level-id]')).find(el=>el.dataset.levelId===id);
 if(!row)return;
 if(educationConfig().classrooms.some(r=>r.levelId===id&&activeEducationRoom(r.id)&&educationRoomInUse(r.id))){showFeedback('This level is in use. Move active assignments and future plans before removing it.');return}
 const saved=educationConfig().levels.find(l=>l.id===id),referenced=saved&&educationLevelReferenced(id);
 if(!confirm(referenced?'This level is in use. Retire it for new placements?':'Remove this level?'))return;
 if(referenced){row.outerHTML=`<div class="education-retired-level" data-retired-level-id="${esc(id)}">${esc(saved.name)} · Retired</div>`;byId('room_group_'+id)?.remove();mpsSettingsChanged();return}
 row.remove();
 byId('room_group_'+id)?.remove();
 mpsSettingsChanged();
}
function educationRoomReferenced(id){
 const visit=value=>value&&typeof value==='object'&&Object.entries(value).some(([key,part])=>(key==='classroomId'&&part===id)||(key==='classroomIds'&&Array.isArray(part)&&part.includes(id))||visit(part));
 return !!visit(db)||!!Object.keys(db.curriculum?.weeks?.[id]||{}).length;
}
function educationRoomInUse(id){
 if(Object.values(db.people?.children||{}).some(child=>{const e=childEnrolment(child);return e?.status==='active'&&(educationPlacement(e)?.classroomId===id||(e.placementHistory||[]).some(p=>p.classroomId===id&&p.effectiveDate>TODAY))}))return true;
 if(Object.values(db.staff?.accounts||{}).some(a=>a.status!=='inactive'&&(a.classroomIds||[]).includes(id)))return true;
 if(Object.values(db.admissions||{}).some(c=>!c.closed&&!c.migrationHistory&&!c.enrolment&&c.confirmedPlacement?.classroomId===id))return true;
 if(Object.values(db.daycare?.bookings||{}).some(b=>b.date>TODAY&&b.status!=='cancelled'&&(b.classroomId===id||(b.classroomIds||[]).includes(id))))return true;
 if(Object.values(db.calendar?.events||{}).some(e=>e.date>=TODAY&&(e.classroomIds||[]).includes(id)))return true;
 return Object.entries(db.curriculum?.weeks?.[id]||{}).some(([date,plan])=>date>=TODAY&&(plan.published||(plan.officialArea&&plan.officialArea!=='Not selected')||(plan.summary&&plan.summary!==emptyClassWeek().summary)||Object.values(plan.days||{}).some(items=>items.length)));
}
function removeEducationRoom(id){
 if(!has('Head Teacher'))return;
 const row=Array.from(document.querySelectorAll('[data-room-id]')).find(el=>el.dataset.roomId===id);
 if(!row)return;
 const group=row.closest('[data-room-group-level]');
 if(group.querySelectorAll('[data-room-id]').length<=1){showFeedback('Keep a classroom in this level. Add another before removing this one.');return}
 if(educationRoomInUse(id)){showFeedback('This classroom is in use. Move active assignments and future plans before removing it.');return}
 const saved=educationRoom(id),referenced=!!saved&&educationRoomReferenced(id);
 if(!confirm(referenced?'Retire this classroom for new placements?':'Remove this classroom?'))return;
 if(referenced)row.outerHTML=`<div class="education-retired-level" data-retired-room-id="${esc(id)}">${esc(saved.name)} · Retired</div>`;
 else row.remove();
 mpsSettingsChanged();
}
function educationClassFields(r){return `<div class="education-room" data-room-id="${esc(r.id)}" data-room-level="${esc(r.levelId)}"><div class="field"><label for="room_name_${esc(r.id)}">Classroom name</label><div class="education-room-edit"><input id="room_name_${esc(r.id)}" type="text" value="${esc(r.name)}">${btn('Remove',`removeEducationRoom('${r.id}')`,'secondary','sm')}</div></div></div>`}
function educationClassroomGroup(l,rooms){return `<div class="education-room-group" id="room_group_${esc(l.id)}" data-room-group-level="${esc(l.id)}"><h4 data-room-level-name>${esc(l.name||'New level')}</h4><div data-room-list>${rooms.filter(r=>!r.retired).map(educationClassFields).join('')}</div>${rooms.filter(r=>r.retired).map(r=>`<div class="education-retired-level" data-retired-room-id="${esc(r.id)}">${esc(r.name)} · Retired</div>`).join('')}${btn('+ Add classroom',`addEducationRoom('${l.id}')`,'secondary','sm')}</div>`}
function addEducationRoom(levelId){if(!has('Head Teacher'))return;const group=Array.from(document.querySelectorAll('[data-room-group-level]')).find(el=>el.dataset.roomGroupLevel===levelId);if(!group||!document.querySelector(`[data-level-id="${levelId}"]`))return;const id='room_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);group.querySelector('[data-room-list]').insertAdjacentHTML('beforeend',educationClassFields({id,name:'',levelId}));mpsSettingsChanged();byId('room_name_'+id).focus()}
function daycareDisableReason(id){
 if(Object.values(db.people?.children||{}).some(child=>{const e=childEnrolment(child);return e?.status==='active'&&e.daycarePlanId===id}))return 'A child currently uses this daycare plan. Change their care arrangement before turning it off.';
 if(Object.values(db.daycare?.bookings||{}).some(b=>b.date>TODAY&&b.status!=='cancelled'&&(b.daycarePlanId||b.coverage?.planId||legacyCarePlan(b.care).id)===id))return 'A future booking uses this daycare plan. Amend that booking before turning it off.';
 return '';
}
function toggleEducationDaycareHours(id){
 const checkbox=byId('hours_'+id+'_offered');
 if(!checkbox.checked){const reason=daycareDisableReason(id);if(reason){checkbox.checked=true;showFeedback(reason);return}}
 for(const suffix of ['start','end'])for(const part of ['', '_hour','_minute','_period'])byId('hours_'+id+'_'+suffix+part).disabled=!checkbox.checked;
 byId('hours_'+id+'_row').classList.toggle('is-inactive',!checkbox.checked);
}
function educationHoursFields(id,label,h){
 const offered=id==='preschool'||h.offered!==false;
 return `<div class="education-hours-plan">${id==='preschool'?'':`<h4>${esc(label)}</h4><label class="check-row education-daycare-offered"><input id="hours_${id}_offered" type="checkbox" ${checked(offered)} onchange="toggleEducationDaycareHours('${id}')"> Offered by this preschool</label>`}<div id="hours_${id}_row" class="education-hours-row ${offered?'':'is-inactive'}">${staffTimeField('Starts',h.start,!offered,'hours_'+id+'_start',label)}${staffTimeField('Ends',h.end,!offered,'hours_'+id+'_end',label)}</div></div>`;
}
function educationSettingsFields(){const c=educationConfig();return `${mpsSchoolTermFields()}<details class="settings-section"><summary>Levels</summary><p>Each Level uses one planning band for activity suggestions. This does not move children or limit admission.</p>${c.levels.filter(l=>!l.retired).map(educationLevelFields).join('')}<div id="add_education_level">${btn('Add level','addEducationLevel()','secondary','sm')}</div>${c.levels.filter(l=>l.retired).map(l=>`<div class="education-retired-level">${esc(l.name)} · Retired</div>`).join('')}</details><details class="settings-section"><summary>Classrooms</summary><div id="education_rooms">${c.levels.filter(l=>!l.retired).map(l=>educationClassroomGroup(l,c.classrooms.filter(r=>r.levelId===l.id))).join('')}</div></details>${curriculumSettingsFields()}<details class="settings-section education-hours" data-settings-section="preschool-hours"><summary>Preschool hours</summary>${educationHoursFields('preschool','Preschool',c.preschool)}</details><details class="settings-section education-hours" data-settings-section="daycare"><summary>Daycare</summary>${c.plans.map(p=>educationHoursFields(p.id,p.name,p)).join('')}<small>Existing authorised bookings keep their recorded hours. Amend a booking explicitly to change its coverage.</small></details>`}
function readEducationSettings(){const c=JSON.parse(JSON.stringify(educationConfig()));
 const edited=Array.from(document.querySelectorAll('[data-level-id]')).map(el=>({id:el.dataset.levelId}));
 for(const l of edited){l.name=val('level_name_'+l.id).trim();l.shortName=val('level_short_'+l.id).trim();const range=val('level_range_'+l.id).split('|').map(Number);l.minMonths=range[0];l.maxMonths=range[1];const old=c.levels.find(item=>item.id===l.id),unchangedLegacy=old&&!mpsB09BandsForRange(old.minMonths,old.maxMonths)&&old.minMonths===l.minMonths&&old.maxMonths===l.maxMonths;if(!l.name||!l.shortName||!(mpsB09BandsForRange(l.minMonths,l.maxMonths)||unchangedLegacy)){const error=new Error('Choose one of the supported planning age ranges for each new or changed Level.');error.levelId=l.id;throw error}}
 const retired=new Set(Array.from(document.querySelectorAll('[data-retired-level-id]')).map(el=>el.dataset.retiredLevelId));
 const original=c.levels;
 c.levels=[...original.map(l=>edited.find(e=>e.id===l.id)||((l.retired||retired.has(l.id))?{...l,retired:true}:null)).filter(Boolean),...edited.filter(l=>!original.some(old=>old.id===l.id))];
 const roomEdits=Array.from(document.querySelectorAll('[data-room-id]')).map(el=>{const id=el.dataset.roomId,old=c.classrooms.find(r=>r.id===id),room={id,name:val('room_name_'+id).trim(),levelId:el.dataset.roomLevel};if(!room.name||!c.levels.some(l=>l.id===room.levelId&&!l.retired))throw new Error('Each classroom needs a name and active level.');if(old&&old.levelId!==room.levelId)throw new Error('An existing classroom retains its level. Create a new classroom and explicitly move children instead.');return room});
 const retiredRooms=new Set(Array.from(document.querySelectorAll('[data-retired-room-id]')).map(el=>el.dataset.retiredRoomId));
 c.classrooms=[...c.classrooms.map(r=>roomEdits.find(e=>e.id===r.id)||(r.retired||retiredRooms.has(r.id)?{...r,retired:true}:c.levels.some(l=>l.id===r.levelId&&l.retired)?{...r,retired:true}:null)).filter(Boolean),...roomEdits.filter(r=>!c.classrooms.some(old=>old.id===r.id))];
 if(educationConfig().classrooms.some(r=>activeEducationRoom(r.id)&&!activeEducationRoom(r.id,c)&&educationRoomInUse(r.id)))throw new Error('Move active classroom assignments and future plans before removing them.');
 if(c.levels.some(l=>!l.retired&&!c.classrooms.some(r=>r.levelId===l.id)))throw new Error('Keep at least one classroom for each level.');
 for(const p of c.plans){p.offered=byId('hours_'+p.id+'_offered').checked;if(p.offered===false&&daycarePlan(p.id).offered!==false){const reason=daycareDisableReason(p.id);if(reason)throw new Error(reason)}}
 for(const [id,h] of [['preschool',c.preschool],...c.plans.filter(p=>p.offered).map(p=>[p.id,p])]){
  for(const [suffix,key] of [['start','start'],['end','end']]){
   const controlId='hours_'+id+'_'+suffix,state=mpsTimeFieldState(controlId);
   if(!state.ok){const error=new Error(state.message);error.fieldId=state.fieldId;throw error}
   h[key]=state.value;
  }
  if(h.start>=h.end){const error=new Error('Enter an end time after the start time.');error.fieldId='hours_'+id+'_end_hour';throw error}
 }
 if(c.plans.some(p=>p.offered&&(p.start>c.preschool.start||p.end<c.preschool.end)))throw new Error('Daycare coverage must include the preschool session.');
 return c;
}

function draftEducationLevels(){return Array.from(document.querySelectorAll('[data-level-id]')).map(el=>({id:el.dataset.levelId,name:val('level_name_'+el.dataset.levelId),shortName:val('level_short_'+el.dataset.levelId)}))}
function addEducationLevel(){if(!has('Head Teacher'))return;const id='level_'+Date.now(),newLevel={id,name:'',shortName:'',minMonths:24,maxMonths:36};byId('add_education_level').insertAdjacentHTML('beforebegin',educationLevelFields(newLevel));byId('education_rooms').insertAdjacentHTML('beforeend',educationClassroomGroup(newLevel,[{id:id+'_a',levelId:id,name:'Class A'}]));mpsSettingsChanged()}
// BQ-092 applied to BQ-094 account/profile/settings contact inputs.
// Existing cross-cutting rule: validate and normalise at every input boundary.

function mpsPhoneCountrySelect(id,selected,label='Phone region'){
  const country=selected||mpsDefaultPhoneCountry();
  return `<div class="field"><label>${esc(label)}</label><select id="${id}">${mpsPhoneCountryOptions().map(x=>`<option value="${x.code}" ${x.code===country?'selected':''}>${esc(x.label)}</option>`).join('')}</select></div>`;
}
function mpsOptionalNormalisePhone(raw,countryCode){
  if(!String(raw||'').trim()) return {ok:true,value:''};
  return mpsNormalisePhone(raw,countryCode);
}

function mpsToggleLatePickupSettings(input){
  for(const id of ['fee_grace','fee_late'])byId(id).disabled=!input.checked;
}
function mpsFeeOrdinalDay(n){return `${n}${n%100>=11&&n%100<=13?'th':{1:'st',2:'nd',3:'rd'}[n%10]||'th'}`}
function mpsUpdateMonthlyDueHelper(input){
  const n=Number(input.value),helper=input.nextElementSibling;
  if(helper)helper.textContent=Number.isInteger(n)&&n>=1&&n<=31?`Invoices are due on the ${mpsFeeOrdinalDay(n)} of each month.`:'Enter a day from 1 to 31.';
}

mpsPreschoolSettingsContent=function(){
  const admin=mpsCurrentIsAccountAdmin(),head=has('Head Teacher');
  if(!admin&&!head) return '';
  const o=db.organization;
  const f=mpsTenantFees();
  const country=o.contactPhoneCountry||mpsDefaultPhoneCountry();
  const phoneField=`<div class="field"><label>Preschool contact phone</label><input id="org_phone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(o.contactPhone||'')}" oninput="this.value=mpsPhoneInput(this.value)" /></div>`;
  const general=admin?`<h3>General</h3>${field('Preschool name',o.name||ORG,'text',false,'org_name')}<div class="form-grid">${mpsPhoneCountrySelect('org_phone_country',country,'Phone region')}${phoneField}</div><div class="field"><label>Preschool timezone</label><select id="org_timezone">${mpsTimezoneOptions(o.timezone)}</select><small>Use the timezone where this preschool operates.</small></div>`:'';
  const feeMoneyField=(label,value,id)=>`<div class="field"><label for="${id}">${esc(label)}</label><div class="fee-money-input"><span aria-hidden="true">Rs</span><input id="${id}" type="number" inputmode="numeric" min="0" step="1" value="${esc(String(value))}"></div></div>`;
  const feeField=(label,value,id)=>field(label,String(value),'number',false,id);
  const monthlyDueField=`<div class="field"><label for="fee_monthly_due_day">Monthly fee due day</label><input id="fee_monthly_due_day" type="number" inputmode="numeric" min="1" max="31" step="1" value="${esc(String(f.monthlyDueDay))}" oninput="mpsUpdateMonthlyDueHelper(this)"><small>Invoices are due on the ${mpsFeeOrdinalDay(f.monthlyDueDay)} of each month.</small></div>`;
  const fees=head?`${educationSettingsFields()}<details class="settings-section fees-settings" data-settings-section="fees" open><summary>Fees</summary><div><div class="field currency-setting"><label for="fee_currency">Currency</label><select id="fee_currency"><option value="LKR">Sri Lankan Rupee (LKR)</option></select><small>Example: Rs 25,000</small></div><h4>Admission</h4><div class="form-grid">${feeMoneyField('Admission fee',f.admissionFee,'fee_admission')}${feeField('Due days after acceptance',f.admissionDueDays,'fee_due')}</div><h4>Monthly fees</h4>${f.monthlyReview?notice('Previous combined fees need review. Enter the agreed base and add-ons before saving.','warn'):''}<div class="form-grid">${feeMoneyField('Preschool monthly fee',f.monthly.preschool,'fee_preschool')}${feeMoneyField('Standard Daycare add-on',f.monthly.daycareAddons?.standard??'','fee_standard')}${feeMoneyField('Extended Daycare add-on',f.monthly.daycareAddons?.extended??'','fee_extended')}${monthlyDueField}</div><h4>Late pickup</h4><label class="check-row late-pickup-setting"><input id="fee_late_enabled" type="checkbox" ${checked(f.latePickupEnabled!==false)} onchange="mpsToggleLatePickupSettings(this)"> Charge a late pickup fee</label><div class="form-grid">${feeField('Grace period (minutes)',f.latePickupGraceMinutes,'fee_grace').replace('<input ',`<input ${f.latePickupEnabled===false?'disabled ':''}`)}${feeMoneyField('Late pickup fee',f.latePickupFee,'fee_late').replace('<input ',`<input ${f.latePickupEnabled===false?'disabled ':''}`)}</div></div></details>`:'';
  return `<div class="preschool-settings" oninput="mpsSettingsChanged()" onchange="mpsSettingsChanged()">${general}${fees}</div>`;
};

mpsSavePreschoolSettings=function(section=null){
  const admin=mpsCurrentIsAccountAdmin(),head=has('Head Teacher');
  if(!admin&&!head){showFeedback('Preschool settings access is required.');return}
  const beforeDb=JSON.parse(JSON.stringify(db));
  const o=db.organization;
  let nextFees=null,nextEducation=null,nextCurriculum=null,nextSchoolYear=null;
  if(head){
    try{nextEducation=readEducationSettings();nextCurriculum=readCurriculumSettings();nextSchoolYear=mpsReadSchoolTermSettings()}catch(error){if(error.levelId&&byId('level_range_'+error.levelId))eliiraFieldError('level_range_'+error.levelId,error.message);else if(error.fieldId&&byId(error.fieldId))eliiraFieldError(error.fieldId,error.message);else if(!byId('school_term_error')||byId('school_term_error').hidden)showFeedback(error.message);return}
    const ids=['fee_admission','fee_due','fee_preschool','fee_standard','fee_extended','fee_grace','fee_late','fee_monthly_due_day'];
    const missing=ids.find(id=>!val(id).trim());if(missing){eliiraFieldError(missing,'Enter this fee or period.');return}
    const values=ids.map(id=>Number(val(id)));
    const invalid=values.findIndex((n,i)=>!Number.isSafeInteger(n)||n<0||(i<3&&n===0)||(i===7&&(n<1||n>31)));if(invalid>=0){eliiraFieldError(ids[invalid],'Enter a valid whole-number fee or period.');return}if(val('fee_currency')!=='LKR'){eliiraFieldError('fee_currency','Choose the supported currency.');return}
    nextFees={currency:'LKR',currencyDisplay:'Rs',admissionFee:values[0],admissionDueDays:values[1],monthly:{preschool:values[2],daycareAddons:{standard:values[3],extended:values[4]}},monthlyDueDay:values[7],latePickupEnabled:byId('fee_late_enabled').checked,latePickupGraceMinutes:values[5],latePickupFee:values[6]};
  }
  // Section-level UI uses this same validated writer; untouched sections retain
  // their exact stored objects, including legacy/history fields and key order.
  if(section){
    if(!['level','room','new-level','operations'].includes(section))nextEducation=null;
    if(section!=='curriculum')nextCurriculum=null;
    if(section!=='academic')nextSchoolYear=null;
    if(section!=='fees')nextFees=null;
  }
  // This is the Level configuration writer for page, modal and planning-setup
  // entry paths. Validate the staged result before assigning it to the store.
  if(nextEducation){const conflict=educationRangeWriteError(educationConfig(),nextEducation);if(conflict){eliiraFieldError('level_range_'+conflict.levelId,conflict.message);return}}
  const saveHeadSettings=()=>{if(nextEducation&&JSON.stringify(o.educationCare)!==JSON.stringify(nextEducation)){o.educationCare=nextEducation;o.settingsHistory.push({at:new Date().toISOString(),byId:currentPersona().id,changes:['education and operating settings updated'],educationSnapshot:JSON.parse(JSON.stringify(nextEducation))})}if(nextCurriculum&&JSON.stringify(mpsTenantCurriculum())!==JSON.stringify(nextCurriculum)){o.curriculum=nextCurriculum;o.settingsHistory.push({at:new Date().toISOString(),by:currentPersona().name,byId:currentPersona().id,changes:['primary curriculum pack updated'],curriculumSnapshot:JSON.parse(JSON.stringify(nextCurriculum))})}if(nextFees&&JSON.stringify(mpsTenantFees())!==JSON.stringify(nextFees)){o.fees=nextFees;o.settingsHistory.push({at:new Date().toISOString(),by:currentPersona().name,byId:currentPersona().id,changes:['fees updated'],feeSnapshot:JSON.parse(JSON.stringify(nextFees))})}if(nextSchoolYear)mpsApplySchoolYear(nextSchoolYear)};
  if(!admin){saveHeadSettings();if(!save()){db=beforeDb;return}mpsSettingsSaved();return}
  if(section&&section!=='preschool'){saveHeadSettings();if(!save()){db=beforeDb;return}mpsSettingsSaved();return}
  const nextName=val('org_name').trim();
  const nextPhoneCountry=val('org_phone_country')||mpsDefaultPhoneCountry();
  const nextPhone=mpsOptionalNormalisePhone(val('org_phone'),nextPhoneCountry);
  const nextTimezone=val('org_timezone');
  if(!nextName){eliiraFieldError('org_name','Enter the preschool name.');return}
  if(!nextPhone.ok){eliiraFieldError('org_phone',nextPhone.error);return}
  if(nextTimezone!==o.timezone&&!confirm(`Change the preschool timezone from ${mpsTimezoneLabel(o.timezone)} to ${mpsTimezoneLabel(nextTimezone)}? This changes how the preschool interprets and displays operational times.`)) return;
  saveHeadSettings();
  const changes=[];
  if(nextName!==o.name) changes.push(`name: ${o.name} → ${nextName}`);
  if(nextPhone.value!==o.contactPhone) changes.push('contact phone updated');
  if(nextTimezone!==o.timezone) changes.push(`timezone: ${o.timezone} → ${nextTimezone}`);
  o.name=nextName;o.contactPhone=nextPhone.value;o.contactPhoneCountry=nextPhoneCountry;o.timezone=nextTimezone;
  if(changes.length)o.settingsHistory.push({at:new Date().toISOString(),by:currentPersona().name,byId:currentPersona().id,changes});
  if(!save()){db=beforeDb;return}mpsSettingsSaved();
};

// Keep the first visible frame on the newest overrides.
render();
// BQ-092 follow-through — apply the approved country-aware contact validation
// to existing secure parent forms as well as newer account/admin surfaces.
// This does not add new mandatory fields; it enforces the contact fields those
// workflows already collect and keeps stored phone values dependable.

function mpsParentApplicationPhoneCountry(caseId){
  const c=db.admissions?.[caseId];
  const d=c?.application?.draft||{};
  return d.phoneCountry||c?.phoneCountry||mpsDefaultPhoneCountry();
}

const _mpsBq092ContactBaseRenderParentApplication=renderParentApplication;
renderParentApplication=function(){
  let html=_mpsBq092ContactBaseRenderParentApplication();
  const caseId=ui().parentApplicationCase;
  const c=db.admissions?.[caseId];
  const d=c?.application?.draft;
  if(!c||!d||ui().parentApplicationStep!==1) return html;
  const country=mpsParentApplicationPhoneCountry(caseId);
  const oldPhone=field('Registered phone',d.phone||c.phone||'','text',false,'pa_phone');
  const phoneField=`<div class="field"><label>Registered phone</label><input id="pa_phone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(d.phone||c.phone||'')}" oninput="this.value=mpsPhoneInput(this.value)" /></div>`;
  return html.replace(oldPhone,`${mpsPhoneCountrySelect('pa_phone_country',country,'Phone region')}${phoneField}`);
};

function mpsValidateParentApplicationPhone(caseId){
  const input=byId('pa_phone');
  if(!input) return true;
  const country=val('pa_phone_country')||mpsParentApplicationPhoneCountry(caseId);
  const phone=mpsNormalisePhone(input.value,country);
  if(!phone.ok)return eliiraFieldError('pa_phone',phone.error);
  input.value=phone.value;
  return true;
}

// Store the Application draft exactly once after contact validation. The older
// helper saved raw phone text before later validation; BQ-092 requires the stored
// draft itself to remain dependable, not merely the final submitted record.
const _mpsBq092ContactBaseSyncApplicationDraft=syncApplicationDraft;
syncApplicationDraft=function(caseId){
  const c=db.admissions?.[caseId];
  if(!c) return;
  const d=c.application.draft||(c.application.draft={});
  ['childName','dob','guardian','service','start'].forEach(k=>{const e=byId('pa_'+k);if(e)d[k]=e.value});
  const input=byId('pa_phone');
  if(input){
    const country=val('pa_phone_country')||mpsParentApplicationPhoneCountry(caseId);
    const phone=mpsNormalisePhone(input.value,country);
    if(phone.ok){d.phone=phone.value;d.phoneCountry=country}
  }
  save();
};

const _mpsBq092ContactBaseAppContinue=appContinue;
appContinue=function(caseId){
  if(!mpsValidateParentApplicationPhone(caseId)) return;
  return _mpsBq092ContactBaseAppContinue(caseId);
};

const _mpsBq092ContactBaseSubmitApplication=submitApplication;
submitApplication=function(caseId){
  if(!mpsValidateParentApplicationPhone(caseId)) return;
  const result=_mpsBq092ContactBaseSubmitApplication(caseId);
  const c=db.admissions?.[caseId];
  if(c?.application?.status==='submitted'&&c.application.draft?.phoneCountry){
    c.phoneCountry=c.application.draft.phoneCountry;
    save();
  }
  return result;
};

function mpsOnboardingPhoneCountry(caseId,record){
  return record?.phoneCountry||db.admissions?.[caseId]?.phoneCountry||mpsDefaultPhoneCountry();
}

const _mpsBq092ContactBaseGuardianCard=guardianCard;
guardianCard=function(g,i){
  let html=_mpsBq092ContactBaseGuardianCard(g,i);
  const caseId=ui().route==='parent-application'?ui().parentApplicationCase:ui().parentOnboardingCase;
  const country=mpsOnboardingPhoneCountry(caseId,g);
  const oldPhone=field('Registered WhatsApp / mobile',g.phone||'','text',false,`po_g${i}_phone`);
  const phoneField=`<div class="field"><label>Registered WhatsApp / mobile</label><input id="po_g${i}_phone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(g.phone||'')}" oninput="this.value=mpsPhoneInput(this.value)" /></div>`;
  return html.replace(oldPhone,`${mpsPhoneCountrySelect(`po_g${i}_phone_country`,country,'Phone region')}${phoneField}`);
};

const _mpsBq092ContactBaseRenderParentOnboarding=renderParentOnboarding;
renderParentOnboarding=function(){
  let html=_mpsBq092ContactBaseRenderParentOnboarding();
  const caseId=ui().route==='parent-application'?ui().parentApplicationCase:ui().parentOnboardingCase;
  const c=db.admissions?.[caseId];
  const o=c?.onboarding;
  if(!c||!o||ui().parentOnboardingStep!==3) return html;
  const e=o.draft?.emergency||{};
  const country=mpsOnboardingPhoneCountry(caseId,e);
  const oldPhone=field('Phone',e.phone||'','text',false,'po_em_phone');
  const phoneField=`<div class="field"><label>Phone</label><input id="po_em_phone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(e.phone||'')}" oninput="this.value=mpsPhoneInput(this.value)" /></div>`;
  return html.replace(oldPhone,`${mpsPhoneCountrySelect('po_em_phone_country',country,'Phone region')}${phoneField}`);
};

function mpsValidateOnboardingContactStep(caseId,step){
  const o=ensureOnboarding(caseId);
  if(step===2){
    for(let i=0;i<(o.draft.guardians||[]).length;i++){
      const input=byId(`po_g${i}_phone`);
      if(!input) continue;
      const country=val(`po_g${i}_phone_country`)||mpsOnboardingPhoneCountry(caseId,o.draft.guardians[i]);
      const phone=mpsOptionalNormalisePhone(input.value,country);
      if(!phone.ok)return eliiraFieldError(`po_g${i}_phone`,`Guardian ${i+1}: ${phone.error}`);
      if(phone.value) input.value=phone.value;
    }
  }
  if(step===3){
    const input=byId('po_em_phone');
    if(input){
      const country=val('po_em_phone_country')||mpsOnboardingPhoneCountry(caseId,o.draft.emergency);
      const phone=mpsNormalisePhone(input.value,country);
      if(!phone.ok)return eliiraFieldError('po_em_phone',`Emergency contact: ${phone.error}`);
      input.value=phone.value;
    }
  }
  return true;
}

const _mpsBq092ContactBaseSyncOnboarding=syncOnboarding;
syncOnboarding=function(caseId,step){
  const before=ensureOnboarding(caseId).draft;
  const guardianBefore=step===2?(before.guardians||[]).map(g=>({phone:g.phone||'',phoneCountry:g.phoneCountry||''})):[];
  const emergencyBefore=step===3?{phone:before.emergency?.phone||'',phoneCountry:before.emergency?.phoneCountry||''}:null;

  _mpsBq092ContactBaseSyncOnboarding(caseId,step);
  const o=ensureOnboarding(caseId);
  const d=o.draft;

  if(step===2){
    (d.guardians||[]).forEach((g,i)=>{
      const country=val(`po_g${i}_phone_country`)||mpsOnboardingPhoneCountry(caseId,g);
      const phone=mpsOptionalNormalisePhone(g.phone,country);
      if(phone.ok){
        g.phone=phone.value;
        g.phoneCountry=country;
      }else{
        g.phone=guardianBefore[i]?.phone||'';
        g.phoneCountry=guardianBefore[i]?.phoneCountry||mpsOnboardingPhoneCountry(caseId,g);
      }
    });
    save();
  }

  if(step===3&&d.emergency){
    const country=val('po_em_phone_country')||mpsOnboardingPhoneCountry(caseId,d.emergency);
    const phone=mpsOptionalNormalisePhone(d.emergency.phone,country);
    if(phone.ok){
      d.emergency.phone=phone.value;
      d.emergency.phoneCountry=country;
    }else{
      d.emergency.phone=emergencyBefore?.phone||'';
      d.emergency.phoneCountry=emergencyBefore?.phoneCountry||mpsOnboardingPhoneCountry(caseId,d.emergency);
    }
    save();
  }
};

const _mpsBq092ContactBaseOnboardingNext=onboardingNext;
onboardingNext=function(caseId){
  const step=ui().parentOnboardingStep;
  if(!mpsValidateOnboardingContactStep(caseId,step)) return;
  return _mpsBq092ContactBaseOnboardingNext(caseId);
};

function mpsNormaliseStoredOnboardingContacts(caseId){
  const c=db.admissions?.[caseId];
  const d=c?.onboarding?.draft;
  if(!c||!d) return false;
  let authorisedPhone=false;
  for(let i=0;i<(d.guardians||[]).length;i++){
    const g=d.guardians[i];
    const country=mpsOnboardingPhoneCountry(caseId,g);
    const phone=mpsOptionalNormalisePhone(g.phone,country);
    if(!phone.ok){if(byId(`po_g${i}_phone`))return eliiraFieldError(`po_g${i}_phone`,phone.error);showFeedback(`Guardian ${i+1}: ${phone.error}`);return false}
    g.phone=phone.value;
    g.phoneCountry=country;
    if(g.legalAuthority==='Yes'&&!!phone.value) authorisedPhone=true;
  }
  if(!authorisedPhone){if(byId('po_g0_phone'))return eliiraFieldError('po_g0_phone','At least one authorised Guardian needs a registered mobile number.');showFeedback('At least one authorised Guardian needs a registered mobile number.');return false}
  const emergencyCountry=mpsOnboardingPhoneCountry(caseId,d.emergency);
  const emergency=mpsNormalisePhone(d.emergency?.phone,emergencyCountry);
  if(!emergency.ok){if(byId('po_ec_phone'))return eliiraFieldError('po_ec_phone',emergency.error);showFeedback(`Emergency contact: ${emergency.error}`);return false}
  d.emergency.phone=emergency.value;
  d.emergency.phoneCountry=emergencyCountry;
  if(d.guardians[0]?.phoneCountry) c.phoneCountry=d.guardians[0].phoneCountry;
  save();
  return true;
}

const _mpsBq092ContactBaseSubmitOnboarding=submitOnboarding;
submitOnboarding=function(caseId){
  if(!mpsNormaliseStoredOnboardingContacts(caseId)) return;
  return _mpsBq092ContactBaseSubmitOnboarding(caseId);
};

