// BQ-094 refinement — useful preschool context in the staff header.
// Replace the generic workspace subtitle with the current preschool date/time,
// calculated from the preschool timezone configured in Preschool settings.

function mpsPreschoolClockTimezone(){
  const configured=String(db.organization?.timezone||'Asia/Colombo');
  try{
    new Intl.DateTimeFormat('en-GB',{timeZone:configured}).format(new Date());
    return configured;
  }catch(_err){
    return 'Asia/Colombo';
  }
}

// An exact instant for new review-fixture events, on the same preschool-local
// date and at the same local time shown by the product shell.
function mpsPreschoolBusinessNow(now=new Date()){
  const timeZone=mpsPreschoolClockTimezone(),businessDate=mpsProductDate(now,timeZone);
  if(businessDate===mpsPreschoolLocalDate(now,timeZone))return new Date(now);
  const wallParts=date=>Object.fromEntries(new Intl.DateTimeFormat('en-GB',{
    timeZone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'
  }).formatToParts(date).map(part=>[part.type,part.value]));
  const current=wallParts(now),[year,month,day]=businessDate.split('-').map(Number);
  const wanted=Date.UTC(year,month-1,day,+current.hour,+current.minute,+current.second,now.getMilliseconds());
  let instant=wanted;
  for(let attempt=0;attempt<4;attempt++){
    const local=wallParts(new Date(instant));
    const shown=Date.UTC(+local.year,+local.month-1,+local.day,+local.hour,+local.minute,+local.second,now.getMilliseconds());
    const difference=wanted-shown;
    if(!difference)break;
    instant+=difference;
  }
  return new Date(instant);
}

function mpsPreschoolClockText(now=new Date()){
  const timeZone=mpsPreschoolClockTimezone();
  // Use the same resolved day as Calendar, planning and teaching, including
  // deliberately frozen review/QA dates. Time always uses preschool settings.
  const dateText=new Intl.DateTimeFormat('en-GB',{
    timeZone:'UTC',weekday:'short',day:'numeric',month:'short',year:'numeric'
  }).format(new Date(`${mpsProductDate(now,timeZone)}T12:00:00Z`)).replace('Sept','Sep').replace(',','');
  const timeText=new Intl.DateTimeFormat('en-US',{
    timeZone,hour:'numeric',minute:'2-digit',hour12:true
  }).format(now);
  return `${dateText} · ${timeText}`;
}

function mpsPreschoolClockHtml(){
  const timeZone=mpsPreschoolClockTimezone();
  return `<span id="mps-preschool-clock" data-timezone="${esc(timeZone)}">${esc(mpsPreschoolClockText())}</span>`;
}

function mpsRefreshPreschoolClock(){
  const timeZone=mpsPreschoolClockTimezone(),date=mpsProductDate(new Date(),timeZone);
  if(date!==TODAY){
    // Refresh date-dependent presentation together; never resave plans/history
    // or navigate away from the selected week merely because midnight passed.
    TODAY=date;
    render();
  }
  const clock=document.getElementById('mps-preschool-clock');
  if(!clock)return;
  clock.dataset.timezone=timeZone;
  clock.textContent=mpsPreschoolClockText();
}

