// Owner review — page-heading simplicity.
// Small eyebrow labels should add context, not repeat the page title or expose
// an internal product/domain label that does not help staff finish the job.

function mpsHeadingText(value){
  return String(value||'').replace(/\s+/g,' ').trim();
}

function mpsSimplifyPageHeadings(root){
  if(!root) return;
  root.querySelectorAll('.page-head').forEach(head=>{
    const eyebrow=head.querySelector('.eyebrow');
    const title=head.querySelector('h2');
    if(!title) return;

    const heading=mpsHeadingText(title.textContent);
    // Owner-approved composed phone headers; Attendance keeps its hierarchy.
    if(['Daycare','Photos & media','Staff','Monthly reports','Reports','Health & safety','Calendar'].includes(heading)){
      head.classList.add('page-head--workspace');
      if(heading==='Photos & media') head.classList.add('page-head--recovery');
      if(heading==='Staff'){
        const action=head.querySelector('.page-actions button');
        if(action?.getAttribute('onclick')==="openModal('staff-account')"&&!action.querySelector('.workspace-action-label-mobile')){
          action.innerHTML='<span class="workspace-action-label-desktop">Add staff account</span><span class="workspace-action-label-mobile">Add staff</span>';
        }
      }
    }
    if(!eyebrow) return;
    const eye=mpsHeadingText(eyebrow.textContent);

    // Daycare covers the whole daycare workspace (including Standard and
    // Extended Daycare). "Extended care" wrongly makes the page sound like it
    // covers only one service. "Today" adds useful operational context instead.
    if(heading==='Daycare'&&eye==='Extended care'){
      eyebrow.textContent='Today';
      return;
    }

    const redundantPair=
      (eye==='Organisation calendar'&&heading==='Calendar')||
      (eye==='Organisation'&&heading==='Staff');

    if(!eye||eye.toLowerCase()===heading.toLowerCase()||redundantPair){
      eyebrow.remove();
    }
  });
}

