// BQ-098 — retain pre-enrolment closure context without adding a lifecycle stage.
function admissionClosureStage(c){
  if(c.closed?.stage) return c.closed.stage;
  if(c.application?.status==='declined') return 'Application';
  return admissionDisplayStage({...c,closed:null});
}
function admissionIsClosedCase(c){return !!c?.closed && c.closed.type!=='Duplicate' && !c.enrolment}
function admissionIsCompletedCase(c){return !!c&&!c.closed&&!c.migrationHistory&&admissionHandoffComplete(c)}
function admissionCanClose(c){return allowed('admissions') && !!c && !c.closed && !c.enrolment}
function admissionClosureLabel(c){
  const stage=admissionClosureStage(c),type=c.closed?.type;
  if(stage==='Application') return type==='Declined'?'Application declined':'Family withdrew during Application';
  if(['Accepted','Admission Fee'].includes(stage)) return `${type==='Released'?'Place released':'Family withdrew'} after acceptance · ${stage}`;
  return `Closed ${stage==='Visit'?'after':'at'} ${stage}`;
}
admissionIsApplicationClosed=function(c){return admissionIsClosedCase(c) && admissionClosureStage(c)==='Application'};
const _bq098Matches=admissionMatchesFilter;
admissionMatchesFilter=function(c,filter){
  if(filter==='Completed admissions')return admissionIsCompletedCase(c);
  if(filter==='Migration history')return !!c.migrationHistory;
  if(admissionIsHistorical(c))return false;
  if(filter==='Duplicates') return c.closed?.type==='Duplicate';
  if(filter==='Closed cases') return admissionIsClosedCase(c);
  if(filter==='Closed') return admissionIsApplicationClosed(c);
  if(c.closed) return false;
  return _bq098Matches(c,filter);
};
function admissionIdentityMatches(c,q){
  q=String(q||'').trim().toLowerCase();const digits=mpsSafeDigits(q);
  return String(c.childName||'').toLowerCase().includes(q) || String(c.guardian||'').toLowerCase().includes(q) || (digits.length>=4&&mpsSafeDigits(c.phone).includes(digits));
}
function admissionsIdentitySearch(q){
  return allowed('admissions')?admissionsRetrievableRecords().filter(c=>admissionIdentityMatches(c,q)):[];
}
let admissionsSearchQuery='';
const _bq098Filtered=admissionsFilteredCases;
admissionsFilteredCases=function(){
  if(admissionsSearchQuery.trim() && allowed('admissions')){
    const matches=admissionsIdentitySearch(admissionsSearchQuery);
    return ui().admissionsStageFilter==='Completed admissions'?matches.filter(admissionIsCompletedCase):matches;
  }
  return _bq098Filtered();
};
filterAdmissions=function(q){
  admissionsSearchQuery=q;
  const list=byId('admissionsCaseItems');
  if(list) list.innerHTML=admissionsFilteredCases().map(caseListItem).join('') || '<div class="empty">No matching admissions cases.</div>';
};
const _bq098Filter=setAdmissionsStageFilter;
setAdmissionsStageFilter=function(stage){
  admissionsSearchQuery='';_bq098Filter(stage);
  if(matchMedia('(min-width:821px)').matches)document.querySelector('.admissions-stage-tabs .tab.active')?.scrollIntoView({block:'nearest',inline:'nearest'});
};
const _bq098Select=setAdmissionCase;
setAdmissionCase=function(id){
  const c=admissionsRetrievableRecords().find(c=>c.id===id);if(!allowed('admissions')||!c)return;
  if(c.migrationHistory)ui().admissionsStageFilter='Migration history';
  else if(admissionIsCompletedCase(c))ui().admissionsStageFilter='Completed admissions';
  else if(c.closed?.type==='Duplicate') ui().admissionsStageFilter='Duplicates';
  else if(admissionIsClosedCase(c)){
    if(ui().admissionsStageFilter!=='Closed'||!admissionIsApplicationClosed(c))ui().admissionsStageFilter='Closed cases';
  }
  else if(!admissionMatchesFilter(c,ui().admissionsStageFilter||'All')) ui().admissionsStageFilter='All';
  admissionsSearchQuery='';_bq098Select(id);
};
const _bq098GlobalSearch=globalSearch;
globalSearch=function(q){
  if(String(q||'').trim()&&allowed('admissions')){
    const c=admissionsRetrievableRecords().find(c=>admissionIdentityMatches(c,q));
    if(c){ui().route='admissions';ui().admissionsStageFilter=admissionIsClosedCase(c)?'Closed cases':'All';setAdmissionCase(c.id);return}
  }
  _bq098GlobalSearch(q);
};
const _bq098CaseItem=caseListItem;
caseListItem=function(c){
  if(!admissionIsClosedCase(c))return _bq098CaseItem(c);
  const outcome=admissionSecondaryOutcome(c);
  return `<div class="case-item ${ui().admissionsCase===c.id?'active':''}" data-stage="Closed" onclick="setAdmissionCase('${c.id}')"><div class="top"><strong>${esc(c.childName)}</strong><span>${badge(outcome||'Closed','grey')}</span></div><div class="meta">${esc(c.guardian)} · ${esc(c.service)}<div class="closure-context">${esc(admissionClosureLabel(c))} · ${esc(c.closed.reason||'Reason not recorded')}</div></div></div>`;
};
const _bq098Overview=admissionOverview;
admissionOverview=function(c){
  const html=_bq098Overview(c);
  if(!admissionCanClose(c))return html;
  const action=`<div class="admission-close-action">${btn('Close admissions case',`openModal('close-admissions-case',{caseId:'${c.id}'})`,'secondary','sm')}</div>`;
  if(html.includes('class="admission-record-actions"'))return html.replace(/(<div class="admission-record-actions"[^>]*>)([\s\S]*?)(<\/div>)/,(_,open,content,close)=>open+content+action+close);
  const end=html.lastIndexOf('</div>');
  return html.slice(0,end)+action+html.slice(end);
};
function admissionClosureOptions(c){
  const stage=admissionDisplayStage(c);
  if(stage==='Application')return ['Declined','Family withdrew'];
  if(['Accepted','Admission Fee'].includes(stage))return ['Place released','Family withdrew after acceptance'];
  return ['Closed'];
}
// One retained closure write for generic and contextual pre-enrolment actions.
// Callers retain their forms and supply their existing contextual history wording.
function persistAdmissionsClosure(id,type,reason,event){
  const c=db.admissions[id];
  if(!admissionCanClose(c)||!String(reason||'').trim())return false;
  const stage=admissionDisplayStage(c),at=new Date().toISOString(),by=mpsAdmissionActor();
  c.closed={type,stage,reason:String(reason).trim(),at,by};
  if(type==='Released')Object.assign(c.closed,{releasedAt:at,releasedBy:by});
  c.followUp=null;
  const history=event||{type:'case_closed',title:admissionClosureLabel(c),detail:`${c.closed.reason} · ${by}`};
  c.events.push({...ev(history.type,history.title,history.detail),at});
  ui().admissionsStageFilter=stage==='Application'?'Closed':'Closed cases';
  ui().admissionsCase=id;ui().admissionsTab='overview';admissionsSearchQuery='';
  save();
  return true;
}
function closeAdmissionsCase(id){
  const c=db.admissions[id];if(!admissionCanClose(c))return;
  const reason=val('case_close_reason').trim(),outcome=val('case_close_outcome')||'Closed';
  if(!reason)return eliiraFieldError('case_close_reason','Enter the reason for closing this admissions case.');
  if(!admissionClosureOptions(c).includes(outcome))return;
  const stage=admissionDisplayStage(c);
  const type={'Place released':'Released','Family withdrew':'Withdrawn','Family withdrew after acceptance':'Withdrawn'}[outcome]||outcome;
  if(!persistAdmissionsClosure(id,type,reason))return;
  if(stage==='Application'&&type==='Declined')c.application.status='declined';
  closeOverlay();
}
const _bq098Modal=modalView;
modalView=function(m){
  if(m.name!=='close-admissions-case')return _bq098Modal(m);
  const c=db.admissions[m.data?.caseId];
  if(!admissionCanClose(c))return modal('Case closure unavailable','',notice('Only authorised Admissions staff can close an active pre-enrolment case.','warn'),btn('Close','closeOverlay()','secondary'));
  const options=admissionClosureOptions(c);
  return modal('Close admissions case',c.childName,`${kv('Current stage',esc(admissionDisplayStage(c)))}${options.length>1?selectField('Outcome',options,options[0],'case_close_outcome'):''}${textArea('Reason (required)','','case_close_reason')}${notice('The case and its history will be retained in Closed cases.','info')}`,`${btn('Cancel','closeOverlay()','secondary')}${btn('Close case',`closeAdmissionsCase('${c.id}')`,'danger')}`);
};
// Historical cases offer evidence, not controls that could resume their journey.
const _bq098Tab=renderAdmissionTab;
renderAdmissionTab=function(c){
  if(!admissionIsClosedCase(c))return _bq098Tab(c);
  const summary=`<div class="card closure-summary"><h3>${esc(admissionClosureLabel(c))}</h3>${kv('Reason',esc(c.closed.reason||'Reason not recorded'))}${c.closed.by?kv('Closed by',esc(c.closed.by)):''}${c.closed.at?kv('Closed on',fmtDate(c.closed.at.slice(0,10))):''}</div>`;
  if(ui().admissionsTab==='timeline')return summary+admissionTimeline(c);
  const html=_bq098Tab(c).replace(/<button\b[^>]*>[\s\S]*?<\/button>/g,'');
  return summary+html;
};
// Closed cases cannot be progressed through stale staff or parent controls.
function admissionUnlessClosed(fn){return function(id,...args){if(db.admissions[id]?.closed)return;return fn(id,...args)}}
