scheduleTour=admissionUnlessClosed(scheduleTour);
sendApplication=admissionUnlessClosed(sendApplication);
submitApplication=admissionUnlessClosed(submitApplication);
acceptApplication=admissionUnlessClosed(acceptApplication);
waitlistApplication=admissionUnlessClosed(waitlistApplication);
returnWaitlistedApplication=admissionUnlessClosed(returnWaitlistedApplication);
