 document.querySelectorAll('[data-settings-level]').forEach(node=>node.dataset.editing=String(!!edit&&(edit.key==='level'&&edit.id===node.dataset.settingsLevel||edit.key==='room'&&edit.levelId===node.dataset.settingsLevel)));
