const _billingCreditUpdateDraft=updateDraftInvoice;
updateDraftInvoice=function(id){const inv=db.billing.invoices[id];if(!allowed('billing'))return;const proposed=inv?invoiceTotal(inv)-(inv.lines[0]?.amount||0)+Number(val('edit_amount')):0;if(inv&&proposed<billingApplied(inv))return billingError('Release credit before reducing the draft below its applied credit.');return _billingCreditUpdateDraft(id)};
const _billingCreditVoid=voidAndReplace;
