  if(!mpsEvidenceChildAllowed(childId,context.roomId)||!mpsNieAssessmentLevels.includes(result)&&!mpsAssessmentNonRatings.includes(result)||ids.some(id=>!db.observations[id]||profileChildKey(db.observations[id].childId)!==childId||!mpsEvidenceChildAllowed(childId,context.roomId))||prepared.some(row=>row.childId===childId))return false;
