const mpsLeanBrandPhrases = [
 ['MPS username','Eliira username'],['MPS login','Eliira login'],['Back to MPS','Back to Eliira'],
 ['Preschool-controlled MPS identity','Preschool-controlled Eliira identity'],
 ['Create a separate MPS account','Create a separate Eliira account'],
 ['one MPS identity','one Eliira identity'],['One person, one MPS account','One person, one Eliira account'],
 ['MPS flagged this candidate','Eliira flagged this candidate'],
 ['MPS has found a possible existing record','Eliira has found a possible existing record'],
 ['MPS never silently merges','Eliira never silently merges'],
 ['MPS will then move to the next match','Eliira will then move to the next match'],
 ['MPS-provided reference','Eliira reference'],['MPS derived','Birthday'],
 ['provided automatically by MPS','provided automatically by Eliira'],
 ['does not decide whether MPS is open','does not decide whether the preschool is open'],
 ['Derived from DOB already held in MPS','From the child’s date of birth'],
 ['Derived from Child DOB already held in MPS','From the child’s date of birth'],
 ['are derived from DOB already held in MPS','come from children’s dates of birth']
];
const mpsHeadTeacherLeanCopy = [
 'What needs your attention today.',
 'Prepare the week for your class.',
 'Record what happened when it is useful.',
 'Create invoices, verify payments, and follow up outstanding balances.',
 'Review Health updates, medication authorisations and incidents in one place.',
 'Find a child and open their profile.',
 'People and responsibilities.',
 'Choose the child whose Health information you need.',
 "Open a child's learning history.",
 'Learning evidence already recorded for this child.'
];
function mpsApplyHeadTeacherLeanPresentation(){
 const roots=[document.getElementById('root'),document.getElementById('overlay')].filter(Boolean);
 // Translate known product-owned text at the display boundary, preserving saved snapshots.
 for(const root of roots){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
   const node=walker.currentNode;
   if(node.parentElement?.closest('script,style,textarea,input,[contenteditable],.actual-record,.lesson-evidence-item,.child-evidence-card,.report-parent-output,.b09-offer,.planned-experience-preview'))continue;
   let text=node.nodeValue;
   for(const [from,to] of mpsLeanBrandPhrases)text=text.split(from).join(to);
   if(text!==node.nodeValue)node.nodeValue=text;
  }
  root.querySelectorAll('[aria-label],[title],[placeholder]').forEach(el=>{
   for(const name of ['aria-label','title','placeholder']){
    const value=el.getAttribute(name);if(value===null)continue;
    let text=value;for(const [from,to] of mpsLeanBrandPhrases)text=text.split(from).join(to);
    if(text!==value)el.setAttribute(name,text);
   }
  });
 }
 if(!governedNieReview||prototypeReviewToolsActive)return;
 const root=document.getElementById('root');if(!root)return;
 // Restrict removals to product-owned subtitles/selectors, never evidence/card descriptions.
 roots.forEach(scope=>scope.querySelectorAll('.page-head p,.workspace-heading p,.health-subject-bar > div > span,.class-progress > p,.modal-head p').forEach(el=>{
  if(mpsHeadTeacherLeanCopy.includes(mpsNormaliseUiText(el.textContent)))el.remove();
 }));
 // One visible entry owns this identical incident action; retain the primary page action.
 const incidentEntry=root.querySelector('.page-head button[onclick="openModal(\'incident\')"]');
 if(incidentEntry)root.querySelectorAll('button[onclick="openModal(\'incident\')"]').forEach(button=>{if(button!==incidentEntry)button.remove()});
 // Existing exception actions stay in the same case detail, behind an explicit disclosure.
 const duplicate=root.querySelector('.admission-record-actions'),closure=root.querySelector('.admission-close-action');
 if(duplicate||closure){
  const anchor=duplicate||closure,details=document.createElement('details');details.className='admission-record-options';
  const summary=document.createElement('summary');summary.textContent='Record options';details.append(summary);
  anchor.before(details);if(duplicate)details.append(duplicate);if(closure)details.append(closure);
 }
 root.querySelectorAll('.teaching-today-item').forEach(card=>{
  // The card badge owns current status; actor/time/reason/history remain below it.
  card.querySelector('.actual-record > strong')?.remove();
  const guidance=card.querySelector('[data-planned-guidance]'),offers=guidance?.querySelectorAll('[data-b09-band]');
  if(offers?.length===1){
   const band=offers[0].getAttribute('data-b09-band'),context=guidance.querySelector('.b09-context')?.textContent||'';
   if(band&&context.startsWith(`Ages ${band} · `))offers[0].querySelector(':scope > strong')?.remove();
  }
 });
}
const _mpsHeadTeacherLeanRender=render;
render=function(){_mpsHeadTeacherLeanRender();mpsApplyHeadTeacherLeanPresentation();};
render();

