  const ids=outcome==='Restrictions apply'?[...new Set(Array.from(document.querySelectorAll('[data-family-legal-guardian]:checked')).map(el=>el.value))]:[];
  if(ids.some(id=>!candidates.has(id))){showFeedback('Choose only current captured Guardians.');return false}
  const checks=Object.fromEntries(['communications','emergency','pickup'].map(key=>[key,!!document.querySelector(`[data-family-legal-check="${key}"]:checked`)]));
  if(outcome==='Restrictions apply'&&!Object.values(checks).every(Boolean)){const first=[...document.querySelectorAll('[data-family-legal-check]')].find(input=>!input.checked);if(first&&!first.id)first.id='family_legal_check_required';return first?eliiraFieldError(first.id,'Confirm this operational record was checked.'):false}
