 if(m?.name==='historical-term-report'){const r=db.reports?.[m.data?.reportId],content=r&&mpsReportFrozen(r);return modal('Historical Term summary','Read-only historical report.',content?mpsBQ159HistoricalParentHtml(content):notice('No approved historical summary is available.','info'),btn('Close','closeOverlay()','secondary'))}
 return mpsBQ159BaseModalView(m);
