function mpsRound2EnhanceForms(root=document){
 let generated=0;
 root.querySelectorAll('.field').forEach(group=>{
  const controls=[...group.querySelectorAll('input:not([type=hidden]),select,textarea')],control=controls[0],label=group.querySelector(':scope > label');if(controls.length!==1||!control||!label)return;
  if(!control.id)control.id=`render_field_${++generated}`;if(!label.htmlFor&&!label.contains(control))label.htmlFor=control.id;
  const helper=Array.from(group.children).find(node=>node.tagName==='SMALL');if(helper){if(!helper.id)helper.id=control.id+'_help';const ids=new Set((control.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean));ids.add(helper.id);control.setAttribute('aria-describedby',[...ids].join(' '))}
 });
 root.querySelectorAll('input[type="search"],input.search,.search,input[placeholder*="Search" i]').forEach(input=>{if(!input.getAttribute('aria-label')&&!input.getAttribute('aria-labelledby')){const label=input.id&&root.querySelector(`label[for="${CSS.escape(input.id)}"]`);input.setAttribute('aria-label',(label?.textContent||input.placeholder||'Search').trim().replace(/…/g,''))}});
}
function mpsRound2TabLabel(group){
 if(group.classList.contains('attendance-tabs'))return 'Attendance views';
 if(group.closest('.health-review-grid')||ui().route==='health')return 'Health views';
 if(ui().route==='lessons')return 'Planning views';if(ui().route==='media')return 'Photos and media views';if(ui().route==='reports')return 'Report views';
 return 'Workspace views';
}
function mpsRound2EnhanceTabs(root=document){
 root.querySelectorAll('.tabs').forEach(group=>{
  const controls=[...group.querySelectorAll(':scope > button.tab')];if(!controls.length)return;
  const filter=group.classList.contains('admissions-stage-tabs')||group.closest('[data-application-outcome-filters]')||group.classList.contains('billing-view-tabs')||controls.some(button=>button.hasAttribute('data-stage-filter'));
  group.setAttribute('role',filter?'group':'tablist');if(!group.getAttribute('aria-label'))group.setAttribute('aria-label',filter?'Filters':mpsRound2TabLabel(group));
  controls.forEach(button=>{if(filter){button.removeAttribute('role');button.setAttribute('aria-pressed',String(button.classList.contains('active')));button.removeAttribute('aria-selected')}else{button.setAttribute('role','tab');button.setAttribute('aria-selected',String(button.classList.contains('active')));button.tabIndex=button.classList.contains('active')?0:-1}});
  if(!filter&&!group.dataset.keyboardTabs){group.dataset.keyboardTabs='true';group.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const tabs=[...group.querySelectorAll(':scope > [role="tab"]')],index=tabs.indexOf(document.activeElement);if(index<0)return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click();queueMicrotask(()=>{const replacement=[...document.querySelectorAll('.tabs[role="tablist"]')].find(candidate=>candidate.getAttribute('aria-label')===group.getAttribute('aria-label'));(replacement?.querySelector('[role="tab"][aria-selected="true"]')||replacement?.querySelectorAll('[role="tab"]')[next])?.focus()})})}
 });
}
function mpsRound2Focusables(dialog){return [...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>!el.hidden&&el.getClientRects().length)}
function mpsRound2RestoreFocus(){
 const ref=mpsRound2ReturnFocus;if(!ref)return;mpsRound2ReturnFocus=null;
 let target=ref.id&&document.getElementById(ref.id);if(!target&&ref.onclick)target=[...document.querySelectorAll('[onclick]')].find(el=>el.getAttribute('onclick')===ref.onclick);if(!target&&ref.text)target=[...document.querySelectorAll('button,a')].find(el=>(el.textContent||'').trim()===ref.text);target?.focus?.();
}
function mpsRound2EnhanceRendered(){
 mpsRound2EnhanceForms();mpsRound2EnhanceTabs();if(ui().route==='admissions')mpsRevealSelectedAdmissionTab();
 const dialog=document.querySelector('#overlay [role="dialog"]');if(dialog&&document.activeElement&&!dialog.contains(document.activeElement))queueMicrotask(()=>{if(!dialog.contains(document.activeElement))dialog.focus()});
 if(!dialog&&mpsRound2OverlayWasOpen){mpsRound2OverlayWasOpen=false;queueMicrotask(mpsRound2RestoreFocus)}
}
document.addEventListener('keydown',event=>{
 const dialog=document.querySelector('#overlay [role="dialog"]');if(!dialog)return;
 if(event.key==='Escape'){const close=dialog.querySelector('.x');if(close){event.preventDefault();close.click()}return}
 if(event.key!=='Tab')return;const focusable=mpsRound2Focusables(dialog);if(!focusable.length){event.preventDefault();dialog.focus();return}const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}
});

const mpsRound2BaseRender=render;
render=function(){mpsRound2FieldSequence=0;const result=mpsRound2BaseRender();mpsRound2EnhanceRendered();return result};
