mpsReportParentMeaning=function(result,childName){
 return childName?({
  'Not Yet':`${childName} is still learning this and needs support.`,
  Emerging:`${childName} is beginning to show this with support.`,
  Developing:`${childName} is growing in confidence and can do some of this independently.`,
  Consistent:`${childName} shows this consistently and independently in different situations.`
 })[result]||null:null;
};

